/* ============================================================
   WHISPERING PINES — every house is a Doom level
   ============================================================ */
:root {
  --bone: #efe6d2;
  --bone-dim: #b9ae96;
  --ink: #0b0a0d;
  --ink-2: #121116;
  --blood: #d9362b;
  --blood-deep: #7d1a16;
  --amber: #ffb347;
  --green: #97d05a;
  --panel: rgba(12, 11, 15, 0.78);
  --line: rgba(239, 230, 210, 0.18);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #07070a;
  color: var(--bone);
  font-family: "IBM Plex Mono", "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

#app { position: fixed; inset: 0; }

#world { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

#fx {
  position: absolute; inset: 0; width: 100%; height: 100%;
  pointer-events: none; z-index: 3;
}

#vignette {
  position: absolute; inset: 0; z-index: 4; pointer-events: none;
  background:
    radial-gradient(ellipse at center, transparent 48%, rgba(0,0,0,0.45) 100%),
    linear-gradient(to bottom, rgba(0,0,0,0.28), transparent 18%, transparent 82%, rgba(0,0,0,0.4));
}
#scanlines {
  position: absolute; inset: 0; z-index: 5; pointer-events: none; opacity: 0.16;
  background: repeating-linear-gradient(to bottom, rgba(0,0,0,0.55) 0px, rgba(0,0,0,0.55) 1px, transparent 1px, transparent 3px);
  mix-blend-mode: multiply;
}
body.no-fx #scanlines, body.no-fx #vignette { display: none; }

.hidden { display: none !important; }
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud button { pointer-events: auto; }

/* ---------- generic bits ---------- */
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
}
.eyebrow {
  font-size: 9px; letter-spacing: 0.24em; color: var(--bone-dim);
  text-transform: uppercase; font-weight: 600;
}
kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 18px; height: 18px; padding: 0 5px;
  border: 1px solid rgba(239,230,210,0.4); border-bottom-width: 2px;
  border-radius: 3px; font: inherit; font-size: 10px; line-height: 1;
  color: var(--bone); background: rgba(255,255,255,0.06);
}
.dot { opacity: 0.4; }

.btn {
  display: block; width: 100%; padding: 14px 18px;
  font-family: inherit; font-size: 12px; font-weight: 700; letter-spacing: 0.18em;
  color: var(--bone); background: rgba(255,255,255,0.05);
  border: 1px solid rgba(239,230,210,0.28);
  cursor: pointer; text-transform: uppercase;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  transition: transform .12s ease, background .15s ease, color .15s ease;
}
.btn:hover { background: rgba(255,255,255,0.11); transform: translateY(-1px); }
.btn:active { transform: translateY(1px); }
.btn-primary {
  color: #170b08;
  background: linear-gradient(180deg, #ff9c4a, #e2542b);
  border-color: #ffb877;
  text-shadow: 0 1px 0 rgba(255,255,255,0.25);
  box-shadow: 0 0 0 1px rgba(0,0,0,0.5), 0 8px 30px rgba(226,84,43,0.28);
}
.btn-primary:hover { background: linear-gradient(180deg, #ffb168, #f06233); }
.btn-ghost { background: transparent; color: var(--bone-dim); }
.link-btn {
  background: none; border: none; color: var(--bone-dim); cursor: pointer;
  font-family: inherit; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase;
  padding: 4px 2px;
}
.link-btn:hover { color: var(--bone); }

/* ---------- title ---------- */
.screen {
  position: absolute; inset: 0; z-index: 40;
  display: flex; align-items: center; justify-content: center;
  padding: calc(24px + var(--safe-top)) calc(24px + var(--safe-right)) calc(24px + var(--safe-bottom)) calc(24px + var(--safe-left));
}
.title-screen {
  background:
    radial-gradient(ellipse at 50% 62%, rgba(0,0,0,0) 0%, rgba(5,4,7,0.55) 55%, rgba(5,4,7,0.94) 100%),
    linear-gradient(180deg, rgba(5,4,7,0.55) 0%, rgba(5,4,7,0.1) 35%, rgba(5,4,7,0.86) 100%);
  flex-direction: column;
  justify-content: flex-end;
  padding-bottom: max(6vh, calc(28px + var(--safe-bottom)));
}
.title-grain {
  position: absolute; inset: 0; pointer-events: none; opacity: .25;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.22'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}
.title-inner { position: relative; width: min(760px, 100%); text-align: center; animation: rise .9s ease both .1s; }
@keyframes rise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }

.kicker {
  font-size: 9px; letter-spacing: 0.36em; color: var(--amber);
  text-transform: uppercase; font-weight: 600;
}
.logo { line-height: .78; margin: 18px 0 0; font-family: "Arial Black", Impact, "Helvetica Neue", sans-serif; }
.logo span { display: block; }
.logo-top {
  font-size: clamp(32px, 8.2vw, 94px); letter-spacing: 0.06em;
  color: var(--bone); text-shadow: 0 2px 0 #1a171c, 0 8px 40px rgba(0,0,0,0.8);
}
.logo-bottom {
  font-size: clamp(64px, 17vw, 190px); letter-spacing: 0.01em;
  background: linear-gradient(180deg, #ffd7a1 0%, #ff9b4e 38%, #c93a26 72%, #761810 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 0 rgba(0,0,0,0.55)) drop-shadow(0 18px 60px rgba(201,58,38,0.35));
  margin-top: -.02em;
}
.title-rule { display: flex; align-items: center; gap: 14px; margin: 22px auto 16px; width: min(400px, 80%); color: var(--amber); font-size: 10px; }
.title-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(255,179,71,0.65), transparent); }
.tagline { font-size: clamp(15px, 2.2vw, 21px); letter-spacing: 0.06em; color: var(--bone); font-style: italic; }
.blurb { margin-top: 12px; font-size: 11px; line-height: 1.8; letter-spacing: 0.05em; color: var(--bone-dim); }
#start-btn { width: min(300px, 80%); margin: 26px auto 0; font-size: 13px; padding: 17px 20px; letter-spacing: 0.3em; }
.title-meta {
  display: flex; flex-wrap: wrap; gap: 18px; justify-content: center;
  margin-top: 20px; font-size: 9px; color: var(--bone-dim); letter-spacing: .1em;
}
.title-meta span { display: inline-flex; align-items: center; gap: 6px; }
.title-foot {
  display: flex; gap: 8px; justify-content: center; align-items: center; flex-wrap: wrap;
  margin-top: 18px; font-size: 9px; color: var(--bone-dim);
}
.title-foot .build { letter-spacing: .14em; opacity: .6; }
.title-scroll {
  position: absolute; bottom: max(12px, var(--safe-bottom)); left: 0; right: 0;
  text-align: center; font-size: 8px; letter-spacing: .4em; color: rgba(239,230,210,0.28);
}

/* ---------- neighbourhood HUD ---------- */
.nh-panel {
  position: absolute; top: calc(20px + var(--safe-top)); left: calc(20px + var(--safe-left));
  width: 290px; padding: 16px 18px 14px;
}
.nh-title { font-size: 21px; font-weight: 400; letter-spacing: .02em; margin: 6px 0 12px; line-height: 1.12; }
.nh-title em { font-style: italic; color: var(--amber); }
.curse-row { display: flex; gap: 7px; margin-bottom: 10px; }
.curse-skull {
  width: 25px; height: 25px; display: grid; place-items: center;
  border: 1px solid rgba(239,230,210,0.22); background: rgba(255,255,255,0.03);
  color: #5b5446; font-size: 13px; position: relative;
}
.curse-skull.cleared { color: #1b130c; background: var(--green); border-color: #bfe88b; }
.curse-skull.current { color: var(--amber); border-color: var(--amber); box-shadow: 0 0 12px rgba(255,179,71,.35) inset; }
.nh-status { font-size: 9px; letter-spacing: .18em; color: var(--bone-dim); }
.needs-panel {
  position: absolute; top: calc(20px + var(--safe-top)); right: calc(20px + var(--safe-right));
  width: 212px; padding: 13px 15px;
  display: flex; flex-direction: column; gap: 6px;
}
.need { display: flex; justify-content: space-between; align-items: center; font-size: 9px; letter-spacing: .08em; color: var(--bone-dim); }
.need b { color: var(--bone); font-weight: 600; display: inline-flex; align-items: center; gap: 5px; }
.mood-bad { color: #ff9b7a !important; }
.plumbob-mini {
  width: 10px; height: 14px; display: inline-block; background: #ff4b3e;
  clip-path: polygon(50% 0, 100% 28%, 80% 100%, 20% 100%, 0 28%);
  box-shadow: 0 0 8px rgba(255,75,62,.8);
}
.map-hint {
  position: absolute; bottom: calc(22px + var(--safe-bottom)); left: calc(20px + var(--safe-left));
  display: inline-flex; gap: 8px; align-items: center;
  background: var(--panel); border: 1px solid var(--line); color: var(--bone-dim);
  font-family: inherit; font-size: 9px; letter-spacing: .16em; padding: 9px 12px; cursor: pointer;
}
.map-hint:hover { color: var(--bone); border-color: rgba(239,230,210,.4); }
.map-hint kbd { background: rgba(255,255,255,.09); }

.prompt {
  position: absolute; left: 50%; bottom: calc(86px + var(--safe-bottom)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 12px; padding: 12px 18px;
  background: rgba(10,9,12,0.9); border: 1px solid rgba(255,179,71,.55);
  box-shadow: 0 0 30px rgba(255,179,71,.16);
  font-size: 11px; letter-spacing: .12em; color: var(--bone); text-transform: uppercase;
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  animation: promptPulse 2.2s ease-in-out infinite;
  pointer-events: auto; cursor: pointer;
}
@keyframes promptPulse { 0%,100% { box-shadow: 0 0 20px rgba(255,179,71,.1); } 50% { box-shadow: 0 0 42px rgba(255,179,71,.3); } }
.prompt kbd { border-color: var(--amber); color: var(--amber); height: 22px; min-width: 22px; font-size: 12px; }
.touch-enter {
  position: absolute; left: 50%; bottom: calc(150px + var(--safe-bottom)); transform: translateX(-50%);
  background: linear-gradient(180deg,#ff9c4a,#e2542b); color: #1a0d08;
  padding: 14px 30px; font-size: 12px; font-weight: 800; letter-spacing: .2em;
  border: 1px solid #ffbd83; border-radius: 4px; pointer-events: auto;
}

.compass {
  position: absolute; left: 50%; top: calc(22px + var(--safe-top)); transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 5px; opacity: .9;
}
.compass-ring {
  width: 46px; height: 46px; border: 1px solid rgba(239,230,210,.3); border-radius: 50%;
  display: grid; place-items: center; background: rgba(10,9,12,.55);
}
#compass-arrow {
  width: 0; height: 0; border-left: 6px solid transparent; border-right: 6px solid transparent;
  border-bottom: 18px solid var(--amber); transform-origin: 50% 70%; transition: transform .1s linear;
  filter: drop-shadow(0 0 6px rgba(255,179,71,.7));
}
#compass-label { font-size: 8px; letter-spacing: .22em; color: var(--bone-dim); }

/* ---------- level HUD ---------- */
.obj-panel {
  position: absolute; top: calc(18px + var(--safe-top)); left: calc(18px + var(--safe-left));
  padding: 12px 16px; min-width: 280px; max-width: 360px;
}
.obj-title { font-size: 15px; letter-spacing: .06em; margin: 3px 0 8px; color: var(--bone); }
.obj-line { display: flex; align-items: center; gap: 8px; font-size: 10px; color: var(--amber); letter-spacing: .06em; }
.obj-dot { width: 6px; height: 6px; background: var(--amber); border-radius: 50%; box-shadow: 0 0 8px var(--amber); animation: blink 1.4s infinite; }
@keyframes blink { 50% { opacity: .25; } }
.obj-sub { font-size: 8px; letter-spacing: .16em; color: var(--bone-dim); margin-top: 6px; }

.minimap-wrap {
  position: absolute; top: calc(18px + var(--safe-top)); right: calc(18px + var(--safe-right));
  padding: 7px; background: rgba(8,8,10,.8);
}
.minimap-wrap canvas { display: block; width: 168px; height: 168px; image-rendering: pixelated; }
.minimap-label {
  display: flex; justify-content: space-between; font-size: 7px; letter-spacing: .2em;
  color: var(--bone-dim); padding: 6px 2px 1px;
}
#lh-floor { color: var(--amber); }

.doom-hud {
  position: absolute; left: 0; right: 0; bottom: 0;
  height: calc(78px + var(--safe-bottom));
  padding-bottom: var(--safe-bottom);
  display: flex; align-items: stretch; justify-content: center;
  background:
    linear-gradient(180deg, rgba(34,24,22,.96), rgba(12,9,10,.98) 55%),
    repeating-linear-gradient(90deg, transparent 0 34px, rgba(255,255,255,.03) 34px 35px);
  border-top: 2px solid #6d4c36;
  box-shadow: 0 -18px 44px rgba(0,0,0,.65);
}
.doom-hud::before {
  content: ""; position: absolute; inset: 4px 0 auto; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255,179,71,.32), transparent);
}
.doom-stat {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  min-width: 92px; padding: 0 12px; border-right: 1px solid rgba(255,179,71,.16);
}
.doom-stat:first-child { border-left: 1px solid rgba(255,179,71,.16); }
.doom-stat.wide { min-width: 118px; }
.doom-label { font-size: 8px; letter-spacing: .22em; color: #b3a48e; margin-bottom: 2px; }
.doom-num {
  font-family: "Arial Black", Impact, sans-serif; font-size: 25px; letter-spacing: .04em;
  color: #ffcf8d; text-shadow: 0 0 14px rgba(255,179,71,.35), 0 2px 0 #2b130a;
  font-variant-numeric: tabular-nums;
}
.doom-num.hp { color: #ff8c74; }
.doom-num.ar { color: #8fd0a0; }
.doom-center {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 0 14px; border-right: 1px solid rgba(255,179,71,.16);
}
#face {
  width: 52px; height: 52px; image-rendering: pixelated; border: 1px solid rgba(255,179,71,.4);
  background: #1b1110; box-shadow: inset 0 0 20px rgba(0,0,0,.7);
}
.face-label { font-size: 7px; letter-spacing: .2em; color: #ff9b7a; margin-top: 4px; }
.key-slot { font-size: 18px; color: #c9c0ad; margin-top: 4px; }
.key-slot.has-key { color: var(--amber); text-shadow: 0 0 12px rgba(255,179,71,.8); }

.weapon-strip {
  position: absolute; right: calc(16px + var(--safe-right)); bottom: calc(88px + var(--safe-bottom));
  display: flex; align-items: center; gap: 8px;
  font-size: 9px; letter-spacing: .18em; color: #d9cbb3;
  background: rgba(10,8,9,.55); border: 1px solid rgba(239,230,210,.14); padding: 6px 10px;
}
.weapon-divider { opacity: .35; }
#weapon-hint { display: inline-flex; gap: 3px; align-items: center; color: #8f826e; }

.messages {
  position: absolute; left: 50%; top: calc(18% + var(--safe-top)); transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 4px; pointer-events: none;
  width: min(520px, 84vw);
}
.msg {
  font-size: 10px; letter-spacing: .14em; text-transform: uppercase;
  color: var(--bone); background: rgba(10,8,12,.72); border-left: 2px solid var(--amber);
  padding: 5px 12px; animation: msgIn .25s ease both;
}
.msg.bad { border-color: var(--blood); color: #ffb3a4; }
.msg.good { border-color: var(--green); color: #d6f5b4; }
@keyframes msgIn { from { opacity: 0; transform: translateY(-6px); } }
.lock-hint {
  position: absolute; left: 50%; top: 55%; transform: translate(-50%,-50%);
  font-size: 10px; letter-spacing: .2em; color: rgba(239,230,210,.55);
  background: rgba(5,5,8,.6); border: 1px solid rgba(239,230,210,.15); padding: 10px 16px;
  pointer-events: none;
}

/* ---------- overlays ---------- */
.screen { background: rgba(5,4,7,.72); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }
.menu-screen, .result-screen, .death-screen, .ending-screen, .map-screen { background: rgba(5,4,7,.82); }
.menu-card, .result-card, .death-card, .ending-card, .intro-card, .map-card {
  position: relative; width: min(520px, 100%);
  background: linear-gradient(180deg, rgba(20,18,22,.98), rgba(11,10,13,.99));
  border: 1px solid rgba(239,230,210,.2);
  padding: 34px 34px 28px;
  clip-path: polygon(22px 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%, 0 22px);
  box-shadow: 0 40px 120px rgba(0,0,0,.7);
  animation: cardIn .35s cubic-bezier(.2,.8,.3,1) both;
}
@keyframes cardIn { from { opacity: 0; transform: translateY(14px) scale(.98); } }
.menu-card { width: min(420px, 100%); }
.menu-card h2 { font-family: "Arial Black", Impact, sans-serif; font-size: 48px; letter-spacing: .08em; margin: 6px 0 24px; color: var(--amber); }
.menu-card .btn { margin-bottom: 8px; }
.menu-controls {
  display: flex; flex-wrap: wrap; gap: 10px 16px; margin-top: 22px;
  padding-top: 16px; border-top: 1px solid var(--line);
  font-size: 9px; color: var(--bone-dim); letter-spacing: .06em;
}
.menu-controls span { display: inline-flex; gap: 5px; align-items: center; }

.intro-screen { background: rgba(5,4,7,.4); backdrop-filter: blur(2px); }
.intro-card { text-align: center; }
.intro-card h2, .result-card h2, .ending-card h2 {
  font-family: "Arial Black", Impact, sans-serif;
  font-size: clamp(34px, 5.2vw, 54px); letter-spacing: .02em; line-height: .96; margin: 10px 0 0;
  color: var(--bone);
}
.intro-rule { width: 70px; height: 2px; background: var(--amber); margin: 18px auto; box-shadow: 0 0 16px rgba(255,179,71,.6); }
.intro-card > p#intro-tagline { font-style: italic; color: var(--bone-dim); font-size: 12px; letter-spacing: .1em; }
.intro-stats, .result-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px;
  background: var(--line); border: 1px solid var(--line); margin: 24px 0;
}
.result-grid { grid-template-columns: repeat(2, 1fr); }
.intro-stats > div, .result-grid > div { background: #121116; padding: 12px 8px; text-align: center; }
.intro-stats span, .result-grid span { display: block; font-size: 7px; letter-spacing: .2em; color: var(--bone-dim); margin-bottom: 5px; }
.intro-stats b, .result-grid b { font-size: 14px; letter-spacing: .06em; color: var(--bone); font-weight: 600; }
.intro-flavor { font-size: 11px; font-style: italic; color: var(--bone-dim); line-height: 1.7; margin-bottom: 22px; }
.intro-card .btn-primary { margin-bottom: 10px; }
.intro-card .link-btn { color: var(--bone-dim); }

.result-card { text-align: center; }
.stamp {
  position: absolute; top: 22px; right: 26px; transform: rotate(8deg);
  border: 2px solid var(--green); color: var(--green); padding: 5px 10px;
  font-size: 11px; font-weight: 800; letter-spacing: .2em; opacity: .9;
  box-shadow: 0 0 20px rgba(151,208,90,.2) inset;
}
.result-flavor { font-style: italic; color: var(--bone-dim); font-size: 11px; line-height: 1.7; margin-bottom: 22px; }
.result-card .btn { margin-top: 0; }

.death-card { text-align: center; border-color: rgba(217,54,43,.5); }
.death-card h2 { font-family: "Arial Black", Impact, sans-serif; font-size: clamp(52px, 9vw, 82px); color: var(--blood); letter-spacing: .04em; margin: 8px 0; text-shadow: 0 0 40px rgba(217,54,43,.4); }
.death-card p { color: var(--bone-dim); font-size: 11px; margin-bottom: 18px; font-style: italic; }
.death-stats { display: flex; justify-content: center; gap: 18px; font-size: 9px; color: var(--bone-dim); letter-spacing: .12em; margin-bottom: 22px; }
.death-stats b { color: var(--bone); }
.death-card .btn { margin-bottom: 8px; }

.ending-card { text-align: center; width: min(580px, 100%); }
.ending-card h2 { color: var(--amber); font-size: clamp(40px, 7vw, 64px); text-shadow: 0 0 50px rgba(255,179,71,.3); }
.ending-card p { color: var(--bone-dim); font-size: 11px; line-height: 1.9; margin: 16px 0 0; }
.ending-card .btn { margin-top: 22px; }

/* ---------- map ---------- */
.map-card { width: min(900px, 100%); padding: 26px 30px; }
.map-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 20px; }
.map-head h2 { font-family: "Arial Black", Impact, sans-serif; font-size: 30px; letter-spacing: .03em; margin-top: 4px; }
.map-body { display: grid; grid-template-columns: minmax(0,1fr) minmax(260px, 1fr); gap: 22px; }
.map-canvas-wrap { background: #0a1410; border: 1px solid var(--line); padding: 8px; }
#map-draw { width: 100%; height: auto; display: block; }
.map-list { display: flex; flex-direction: column; gap: 8px; max-height: 380px; overflow-y: auto; }
.map-item {
  display: flex; align-items: center; gap: 12px; padding: 11px 12px;
  border: 1px solid var(--line); background: rgba(255,255,255,.02); cursor: pointer;
  transition: background .15s, border-color .15s;
}
.map-item:hover { background: rgba(255,255,255,.055); border-color: rgba(239,230,210,.35); }
.map-item.locked { opacity: .45; cursor: not-allowed; }
.map-item .mi-icon { width: 26px; height: 26px; display: grid; place-items: center; border: 1px solid var(--line); font-size: 12px; flex: none; }
.map-item.cleared .mi-icon { background: var(--green); color: #16200d; border-color: var(--green); }
.map-item .mi-body { flex: 1; min-width: 0; }
.map-item .mi-name { font-size: 11px; letter-spacing: .06em; margin-bottom: 2px; }
.map-item .mi-sub { font-size: 8px; letter-spacing: .12em; color: var(--bone-dim); }
.map-item .mi-status { font-size: 8px; letter-spacing: .16em; color: var(--amber); white-space: nowrap; }
.map-item.cleared .mi-status { color: var(--green); }
.map-foot { margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line); font-size: 8px; letter-spacing: .16em; color: var(--bone-dim); text-align: center; }

/* ---------- markers ---------- */
#markers { position: absolute; inset: 0; z-index: 8; pointer-events: none; overflow: hidden; }
.marker {
  position: absolute; transform: translate(-50%, -100%);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  pointer-events: none; transition: opacity .2s;
}
.marker .mk-pin {
  padding: 4px 8px; font-size: 8px; letter-spacing: .12em; text-transform: uppercase;
  background: rgba(8,7,10,.82); border: 1px solid rgba(255,179,71,.5); color: var(--bone);
  white-space: nowrap; clip-path: polygon(5px 0,100% 0,100% calc(100% - 5px),calc(100% - 5px) 100%,0 100%,0 5px);
}
.marker .mk-pin b { color: var(--amber); }
.marker.cleared .mk-pin { border-color: var(--green); }
.marker.cleared .mk-pin b { color: var(--green); }
.marker.locked .mk-pin { border-color: rgba(239,230,210,.22); color: var(--bone-dim); }
.marker .mk-line { width: 1px; height: 14px; background: linear-gradient(rgba(255,179,71,.7), transparent); }
.marker.cleared .mk-line { background: linear-gradient(rgba(151,208,90,.7), transparent); }

/* ---------- toast ---------- */
.toast {
  position: absolute; left: 50%; bottom: calc(110px + var(--safe-bottom)); transform: translateX(-50%);
  background: rgba(10,9,12,.94); border: 1px solid var(--amber); color: var(--bone);
  padding: 10px 18px; font-size: 10px; letter-spacing: .14em; text-transform: uppercase;
  z-index: 60; animation: toastIn .3s ease both; pointer-events: none;
  max-width: 86vw; text-align: center;
}
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, 8px); } }

#fade {
  position: absolute; inset: 0; z-index: 100; background: #07060a; opacity: 0;
  transition: opacity .32s ease; pointer-events: none;
}
#fade.on { opacity: 1; pointer-events: auto; }

/* ---------- touch ---------- */
.touch { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
.touch .stick {
  position: absolute; left: calc(24px + var(--safe-left)); bottom: calc(24px + var(--safe-bottom));
  width: 118px; height: 118px; border-radius: 50%;
  border: 1px solid rgba(239,230,210,.28); background: rgba(10,9,12,.32);
  pointer-events: none; display: none;
}
.stick.active { display: block; }
.stick-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px;
  border-radius: 50%; background: rgba(239,230,210,.25); border: 1px solid rgba(239,230,210,.5);
}
.touch-right {
  position: absolute; right: calc(18px + var(--safe-right)); bottom: calc(20px + var(--safe-bottom));
  display: flex; flex-direction: column; align-items: flex-end; gap: 10px; pointer-events: none;
}
.tbtn {
  pointer-events: auto; font-family: inherit; font-weight: 700; letter-spacing: .12em;
  color: var(--bone); background: rgba(10,9,12,.62); border: 1px solid rgba(239,230,210,.35);
  border-radius: 50%; width: 62px; height: 62px; font-size: 9px;
  touch-action: none;
}
.tbtn.fire { width: 78px; height: 78px; font-size: 10px; border-color: rgba(217,54,43,.8); background: rgba(80,16,13,.55); color: #ffb3a4; }
.tbtn.use { width: 54px; height: 54px; }
.tbtn.swap, .tbtn.map { width: 44px; height: 44px; font-size: 7px; color: var(--bone-dim); }
.tbtn:active { background: rgba(255,179,71,.35); }

/* ---------- mobile ---------- */
@media (max-width: 820px) {
  .needs-panel { display: none; }
  .nh-panel { width: 220px; padding: 11px 13px; }
  .nh-title { font-size: 16px; margin: 4px 0 8px; }
  .curse-skull { width: 20px; height: 20px; font-size: 10px; }
  .nh-status { font-size: 8px; }
  .map-hint { font-size: 8px; padding: 7px 9px; }
  .compass { top: calc(12px + var(--safe-top)); }
  .obj-panel { min-width: 0; max-width: 52vw; padding: 9px 11px; }
  .obj-title { font-size: 11px; }
  .obj-sub { display: none; }
  .minimap-wrap { padding: 5px; }
  .minimap-wrap canvas { width: 108px; height: 108px; }
  .minimap-label { font-size: 6px; padding-top: 4px; }
  .doom-hud { height: calc(66px + var(--safe-bottom)); }
  .doom-stat { min-width: 54px; padding: 0 7px; }
  .doom-stat.wide { min-width: 80px; }
  .doom-stat.keys { display: none; }
  .doom-num { font-size: 18px; }
  .doom-label { font-size: 6px; }
  .doom-center { padding: 0 7px; }
  #face { width: 38px; height: 38px; }
  .face-label { display: none; }
  .weapon-strip { bottom: calc(76px + var(--safe-bottom)); font-size: 8px; padding: 5px 7px; }
  .weapon-strip #weapon-hint { display: none; }
  .messages { top: calc(27% + var(--safe-top)); }
  .msg { font-size: 8px; padding: 4px 9px; }
  .prompt { bottom: calc(170px + var(--safe-bottom)); font-size: 9px; }
  .title-meta { display: none; }
  .map-body { grid-template-columns: 1fr; }
  .map-list { max-height: 150px; }
  .map-card { padding: 20px 18px; }
  .map-head h2 { font-size: 22px; }
  .menu-card, .result-card, .death-card, .ending-card, .intro-card { padding: 26px 20px 22px; }
  .intro-card h2, .result-card h2 { font-size: 30px; }
  .map-hint span { display: none; }
  .title-screen { justify-content: center; padding-bottom: calc(20px + var(--safe-bottom)); }
  .blurb { font-size: 10px; }
  #start-btn { margin-top: 20px; }
  .title-foot .build { display: none; }
}

@media (max-height: 620px) {
  .intro-stats { margin: 14px 0; }
  .intro-flavor { display: none; }
  .intro-card { padding: 20px 24px; }
  .intro-card h2 { font-size: 28px; }
  .title-scroll { display: none; }
  .blurb { display: none; }
}

import * as THREE from 'three';

/* ============================================================
   Procedural textures — every pixel is generated at runtime.
   ============================================================ */
const cache = new Map();

function canvas2d(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  return { c, ctx };
}

function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function finish(c, { repeat = [1, 1], nearest = true, srgb = true } = {}) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat[0], repeat[1]);
  t.magFilter = nearest ? THREE.NearestFilter : THREE.LinearFilter;
  t.minFilter = THREE.LinearMipmapLinearFilter;
  t.generateMipmaps = true;
  t.anisotropy = 4;
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  t.needsUpdate = true;
  return t;
}

function cached(key, factory) {
  if (!cache.has(key)) cache.set(key, factory());
  return cache.get(key);
}

const hex = (n) => '#' + n.toString(16).padStart(6, '0');

/* ---------------- ground & neighborhood ---------------- */

export function grassTexture() {
  return cached('grass', () => {
    const { c, ctx } = canvas2d(256, 256);
    const r = rng(7);
    ctx.fillStyle = '#4d6b32'; ctx.fillRect(0, 0, 256, 256);
    for (let i = 0; i < 2400; i++) {
      const x = r() * 256, y = r() * 256;
      const g = 70 + r() * 70;
      ctx.fillStyle = `rgba(${Math.floor(g * 0.55)},${Math.floor(g)},${Math.floor(g * 0.35)},${0.25 + r() * 0.5})`;
      ctx.fillRect(x, y, 1 + r() * 2, 1 + r() * 3);
    }
    for (let i = 0; i < 14; i++) {
      ctx.fillStyle = `rgba(90,80,40,${0.05 + r() * 0.08})`;
      ctx.beginPath();
      ctx.ellipse(r() * 256, r() * 256, 10 + r() * 40, 6 + r() * 24, r() * 6, 0, 7);
      ctx.fill();
    }
    return finish(c, { repeat: [26, 26] });
  });
}

export function asphaltTexture() {
  return cached('asphalt', () => {
    const { c, ctx } = canvas2d(256, 256);
    const r = rng(19);
    ctx.fillStyle = '#25252a'; ctx.fillRect(0, 0, 256, 256);
    for (let i = 0; i < 3200; i++) {
      const g = 20 + r() * 55;
      ctx.fillStyle = `rgba(${g},${g},${g + 3},${0.25 + r() * 0.5})`;
      ctx.fillRect(r() * 256, r() * 256, 1 + r() * 2, 1 + r() * 2);
    }
    ctx.strokeStyle = 'rgba(10,10,12,0.5)';
    for (let i = 0; i < 5; i++) {
      ctx.beginPath();
      let x = r() * 256, y = r() * 256;
      ctx.moveTo(x, y);
      for (let j = 0; j < 4; j++) { x += (r() - 0.5) * 50; y += (r() - 0.5) * 50; ctx.lineTo(x, y); }
      ctx.stroke();
    }
    return finish(c, { repeat: [10, 10] });
  });
}

export function sidewalkTexture() {
  return cached('sidewalk', () => {
    const { c, ctx } = canvas2d(256, 256);
    const r = rng(31);
    ctx.fillStyle = '#8f8b7e'; ctx.fillRect(0, 0, 256, 256);
    for (let i = 0; i < 1800; i++) {
      const g = 100 + r() * 60;
      ctx.fillStyle = `rgba(${g},${g - 4},${g - 12},${0.2 + r() * 0.4})`;
      ctx.fillRect(r() * 256, r() * 256, 2, 2);
    }
    ctx.strokeStyle = 'rgba(60,58,50,0.75)'; ctx.lineWidth = 3;
    for (let i = 0; i <= 2; i++) {
      ctx.beginPath(); ctx.moveTo(i * 128, 0); ctx.lineTo(i * 128, 256); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, i * 128); ctx.lineTo(256, i * 128); ctx.stroke();
    }
    return finish(c, { repeat: [8, 8] });
  });
}

export function concreteTexture(tint = '#7d786c') {
  return cached('concrete' + tint, () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng(53);
    ctx.fillStyle = tint; ctx.fillRect(0, 0, 128, 128);
    for (let i = 0; i < 900; i++) {
      ctx.fillStyle = `rgba(255,255,255,${r() * 0.08})`;
      ctx.fillRect(r() * 128, r() * 128, 1, 1);
      ctx.fillStyle = `rgba(0,0,0,${r() * 0.12})`;
      ctx.fillRect(r() * 128, r() * 128, 1, 1);
    }
    return finish(c, { repeat: [3, 3] });
  });
}

export function sidingTexture(color, trim = '#d7d1bd') {
  return cached('siding' + color + trim, () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng(71);
    ctx.fillStyle = color; ctx.fillRect(0, 0, 128, 128);
    for (let y = 0; y < 128; y += 10) {
      ctx.fillStyle = 'rgba(0,0,0,0.17)'; ctx.fillRect(0, y + 8, 128, 2);
      ctx.fillStyle = 'rgba(255,255,255,0.09)'; ctx.fillRect(0, y, 128, 1);
    }
    for (let i = 0; i < 240; i++) {
      ctx.fillStyle = `rgba(0,0,0,${r() * 0.05})`;
      ctx.fillRect(r() * 128, r() * 128, 1 + r() * 2, 1);
    }
    return finish(c, { repeat: [2.2, 1.6] });
  });
}

export function brickTexture(base = '#8c4a37', mortar = '#c9bda6') {
  return cached('brick' + base + mortar, () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng(97);
    ctx.fillStyle = mortar; ctx.fillRect(0, 0, 128, 128);
    const bw = 32, bh = 16;
    for (let row = 0; row < 8; row++) {
      const off = row % 2 ? bw / 2 : 0;
      for (let col = -1; col < 5; col++) {
        const x = col * bw + off + 2, y = row * bh + 2;
        const shade = 0.82 + r() * 0.3;
        const c0 = parseInt(base.slice(1), 16);
        const rr = Math.min(255, ((c0 >> 16) & 255) * shade);
        const gg = Math.min(255, ((c0 >> 8) & 255) * shade);
        const bb = Math.min(255, (c0 & 255) * shade);
        ctx.fillStyle = `rgb(${rr|0},${gg|0},${bb|0})`;
        ctx.fillRect(x, y, bw - 4, bh - 4);
      }
    }
    return finish(c, { repeat: [2, 2] });
  });
}

export function roofTexture(color = '#4a3230') {
  return cached('roof' + color, () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng(113);
    ctx.fillStyle = color; ctx.fillRect(0, 0, 128, 128);
    for (let row = 0; row < 16; row++) {
      const y = row * 8;
      const off = row % 2 ? 8 : 0;
      for (let col = -1; col < 9; col++) {
        const x = col * 16 + off;
        const sh = 0.78 + r() * 0.32;
        ctx.fillStyle = `rgba(${Math.floor(30 * sh)},${Math.floor(22 * sh)},${Math.floor(20 * sh)},0.45)`;
        ctx.fillRect(x + 1, y + 1, 14, 6);
        ctx.fillStyle = 'rgba(0,0,0,0.35)'; ctx.fillRect(x, y + 7, 16, 1);
      }
    }
    return finish(c, { repeat: [3, 2] });
  });
}

export function hedgeTexture() {
  return cached('hedge', () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng(131);
    ctx.fillStyle = '#2c421f'; ctx.fillRect(0, 0, 128, 128);
    for (let i = 0; i < 1100; i++) {
      const g = 45 + r() * 70;
      ctx.fillStyle = `rgba(${g * 0.45},${g},${g * 0.32},${0.35 + r() * 0.5})`;
      const x = r() * 128, y = r() * 128;
      ctx.beginPath(); ctx.arc(x, y, 1 + r() * 3, 0, 7); ctx.fill();
    }
    return finish(c, { repeat: [2, 2] });
  });
}

/* ---------------- dungeon themes ---------------- */

const WALL_PATTERNS = {
  stripe: (ctx, w, h, t, r) => {
    ctx.fillStyle = t.wall[0]; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = t.wall[1];
    for (let x = 0; x < w; x += 32) ctx.fillRect(x, 0, 12, h);
    ctx.fillStyle = 'rgba(0,0,0,0.16)';
    for (let x = 0; x < w; x += 32) ctx.fillRect(x + 30, 0, 2, h);
    const grd = ctx.createLinearGradient(0, 0, 0, h);
    grd.addColorStop(0, 'rgba(255,255,255,0.07)');
    grd.addColorStop(0.5, 'rgba(0,0,0,0.05)');
    grd.addColorStop(1, 'rgba(0,0,0,0.35)');
    ctx.fillStyle = grd; ctx.fillRect(0, 0, w, h);
  },
  tile: (ctx, w, h, t, r) => {
    ctx.fillStyle = t.wall[0]; ctx.fillRect(0, 0, w, h);
    const s = 32;
    for (let y = 0; y < h; y += s) {
      for (let x = 0; x < w; x += s) {
        if ((x / s + y / s) % 2 === 0) { ctx.fillStyle = t.wall[1]; ctx.fillRect(x, y, s, s); }
      }
    }
    ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 2;
    for (let i = 0; i <= w; i += s) { ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, h); ctx.stroke(); }
    for (let i = 0; i <= h; i += s) { ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(w, i); ctx.stroke(); }
    const grd = ctx.createLinearGradient(0, 0, 0, h);
    grd.addColorStop(0, 'rgba(255,255,255,0.05)');
    grd.addColorStop(1, 'rgba(0,0,0,0.34)');
    ctx.fillStyle = grd; ctx.fillRect(0, 0, w, h);
  },
  panel: (ctx, w, h, t, r) => {
    ctx.fillStyle = t.wall[0]; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = t.wall[1];
    for (let y = 8; y < h; y += 44) for (let x = 8; x < w; x += 44) {
      ctx.fillRect(x, y, 32, 30);
      ctx.fillStyle = 'rgba(0,0,0,0.2)'; ctx.fillRect(x, y + 30, 32, 3);
      ctx.fillStyle = t.wall[1];
    }
    ctx.fillStyle = 'rgba(0,0,0,0.24)';
    for (let x = 0; x < w; x += 44) ctx.fillRect(x, 0, 3, h);
    for (let y = 0; y < h; y += 44) ctx.fillRect(0, y, w, 3);
  },
  flesh: (ctx, w, h, t, r) => {
    ctx.fillStyle = t.wall[0]; ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 30; i++) {
      ctx.fillStyle = `rgba(${100 + r() * 80},${20 + r() * 30},${20 + r() * 30},${0.35 + r() * 0.4})`;
      ctx.beginPath();
      ctx.ellipse(r() * w, r() * h, 6 + r() * 24, 4 + r() * 14, r() * 6, 0, 7);
      ctx.fill();
    }
    ctx.strokeStyle = 'rgba(60,10,12,0.6)'; ctx.lineWidth = 2;
    for (let i = 0; i < 10; i++) {
      ctx.beginPath();
      let x = r() * w, y = r() * h; ctx.moveTo(x, y);
      for (let j = 0; j < 3; j++) { x += (r() - 0.5) * 50; y += (r() - 0.5) * 50; ctx.lineTo(x, y); }
      ctx.stroke();
    }
  },
};

export function hellWallTexture(theme) {
  return cached('hw' + theme.id, () => {
    const { c, ctx } = canvas2d(256, 256);
    const r = rng(theme.seed || 3);
    (WALL_PATTERNS[theme.pattern] || WALL_PATTERNS.stripe)(ctx, 256, 256, theme, r);
    // grime + blood
    for (let i = 0; i < 240; i++) {
      ctx.fillStyle = `rgba(0,0,0,${r() * 0.14})`;
      ctx.fillRect(r() * 256, r() * 256, 1 + r() * 4, 1 + r() * 8);
    }
    if (theme.blood !== false) {
      for (let i = 0; i < 5; i++) {
        const x = r() * 256, y = r() * 180;
        ctx.fillStyle = `rgba(90,10,8,${0.35 + r() * 0.35})`;
        ctx.beginPath(); ctx.ellipse(x, y, 4 + r() * 12, 8 + r() * 22, 0, 0, 7); ctx.fill();
        for (let j = 0; j < 4; j++) ctx.fillRect(x + (r() - 0.5) * 18, y + 6, 1 + r() * 2, 6 + r() * 18);
      }
    }
    return finish(c, { repeat: [1, 1] });
  });
}

export function hellFloorTexture(theme) {
  return cached('hf' + theme.id, () => {
    const { c, ctx } = canvas2d(256, 256);
    const r = rng((theme.seed || 3) + 99);
    ctx.fillStyle = theme.floor[0]; ctx.fillRect(0, 0, 256, 256);
    const s = 64;
    for (let y = 0; y < 256; y += s) for (let x = 0; x < 256; x += s) {
      const v = 0.82 + r() * 0.36;
      const base = theme.floor[1];
      const c0 = parseInt(base.slice(1), 16);
      const rr = Math.min(255, ((c0 >> 16) & 255) * v);
      const gg = Math.min(255, ((c0 >> 8) & 255) * v);
      const bb = Math.min(255, (c0 & 255) * v);
      ctx.fillStyle = `rgb(${rr|0},${gg|0},${bb|0})`;
      ctx.fillRect(x + 2, y + 2, s - 4, s - 4);
      ctx.fillStyle = 'rgba(255,255,255,0.05)'; ctx.fillRect(x + 2, y + 2, s - 4, 2);
    }
    ctx.strokeStyle = 'rgba(0,0,0,0.4)'; ctx.lineWidth = 2;
    for (let i = 0; i <= 256; i += s) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 256); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(256, i); ctx.stroke();
    }
    for (let i = 0; i < 20; i++) {
      ctx.fillStyle = `rgba(60,6,6,${0.12 + r() * 0.3})`;
      ctx.beginPath(); ctx.ellipse(r() * 256, r() * 256, 8 + r() * 34, 4 + r() * 20, r() * 6, 0, 7); ctx.fill();
    }
    return finish(c, { repeat: [14, 14] });
  });
}

export function ceilingTexture(theme) {
  return cached('ceil' + theme.id, () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng((theme.seed || 3) + 17);
    ctx.fillStyle = theme.ceil || '#17151a'; ctx.fillRect(0, 0, 128, 128);
    for (let i = 0; i < 400; i++) {
      ctx.fillStyle = `rgba(255,255,255,${r() * 0.03})`;
      ctx.fillRect(r() * 128, r() * 128, 1, 1);
    }
    ctx.strokeStyle = 'rgba(0,0,0,0.4)'; ctx.lineWidth = 1;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath(); let x = r() * 128, y = r() * 128; ctx.moveTo(x, y);
      for (let j = 0; j < 3; j++) { x += (r() - .5) * 40; y += (r() - .5) * 40; ctx.lineTo(x, y); }
      ctx.stroke();
    }
    return finish(c, { repeat: [7, 7] });
  });
}

export function metalTexture(base = '#5a5d63', accent = '#2a2c31') {
  return cached('metal' + base + accent, () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng(151);
    ctx.fillStyle = base; ctx.fillRect(0, 0, 128, 128);
    for (let i = 0; i < 700; i++) {
      ctx.fillStyle = `rgba(255,255,255,${r() * 0.05})`;
      ctx.fillRect(r() * 128, r() * 128, 1 + r() * 3, 1);
    }
    ctx.strokeStyle = accent; ctx.lineWidth = 3;
    ctx.strokeRect(6, 6, 116, 116);
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    for (let x = 12; x < 128; x += 26) { ctx.beginPath(); ctx.arc(x, 12, 2, 0, 7); ctx.fill(); }
    return finish(c, { repeat: [1, 1] });
  });
}

export function doorTexture(theme) {
  return cached('door' + theme.id, () => {
    const { c, ctx } = canvas2d(128, 256);
    ctx.fillStyle = theme.door || '#4a3d33'; ctx.fillRect(0, 0, 128, 256);
    ctx.fillStyle = 'rgba(0,0,0,0.28)';
    ctx.fillRect(14, 14, 100, 100); ctx.fillRect(14, 132, 100, 100);
    ctx.fillStyle = 'rgba(255,255,255,0.07)';
    ctx.fillRect(14, 14, 100, 3); ctx.fillRect(14, 132, 100, 3);
    ctx.strokeStyle = theme.accent || '#c9a34e'; ctx.lineWidth = 3;
    ctx.strokeRect(6, 6, 116, 244);
    // hazard stripe
    ctx.save(); ctx.beginPath(); ctx.rect(0, 114, 128, 14); ctx.clip();
    ctx.fillStyle = '#d8b23c'; ctx.fillRect(0, 114, 128, 14);
    ctx.fillStyle = '#181410';
    for (let x = -20; x < 140; x += 20) { ctx.beginPath(); ctx.moveTo(x, 128); ctx.lineTo(x + 10, 114); ctx.lineTo(x + 20, 114); ctx.lineTo(x + 10, 128); ctx.fill(); }
    ctx.restore();
    // handle
    ctx.fillStyle = theme.accent || '#c9a34e';
    ctx.fillRect(96, 196, 14, 26);
    return finish(c, { repeat: [1, 1] });
  });
}

export function bloodTexture() {
  return cached('blood', () => {
    const { c, ctx } = canvas2d(128, 128);
    const r = rng(177);
    for (let i = 0; i < 26; i++) {
      const x = 20 + r() * 88, y = 20 + r() * 88;
      ctx.fillStyle = `rgba(${70 + r() * 60},${6 + r() * 10},${6 + r() * 10},${0.4 + r() * 0.5})`;
      ctx.beginPath(); ctx.ellipse(x, y, 3 + r() * 18, 2 + r() * 12, r() * 6, 0, 7); ctx.fill();
    }
    for (let i = 0; i < 50; i++) {
      ctx.fillStyle = `rgba(80,8,8,${0.3 + r() * 0.5})`;
      ctx.beginPath(); ctx.arc(20 + r() * 88, 20 + r() * 88, 0.5 + r() * 2.2, 0, 7); ctx.fill();
    }
    return finish(c, { repeat: [1, 1], nearest: true });
  });
}

export function pentagramTexture(color = '#c22a1d') {
  return cached('penta' + color, () => {
    const { c, ctx } = canvas2d(128, 128);
    ctx.strokeStyle = color; ctx.fillStyle = color;
    ctx.lineWidth = 3; ctx.globalAlpha = 0.85;
    ctx.beginPath(); ctx.arc(64, 64, 54, 0, 7); ctx.stroke();
    ctx.beginPath(); ctx.arc(64, 64, 47, 0, 7); ctx.lineWidth = 1; ctx.stroke();
    const pts = [];
    for (let i = 0; i < 5; i++) {
      const a = -Math.PI / 2 + i * Math.PI * 2 / 5;
      pts.push([64 + Math.cos(a) * 48, 64 + Math.sin(a) * 48]);
    }
    ctx.lineWidth = 3; ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const p = pts[(i * 2) % 5];
      i === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1]);
    }
    ctx.closePath(); ctx.stroke();
    ctx.globalAlpha = 0.5;
    for (let i = 0; i < 20; i++) {
      const a = i / 20 * Math.PI * 2;
      ctx.fillRect(64 + Math.cos(a) * 38 - 1, 64 + Math.sin(a) * 38 - 1, 2, 2);
    }
    return finish(c, { repeat: [1, 1] });
  });
}

export function glowTexture(color = '#ffb347') {
