    g.addColorStop(0.25, color + 'cc');
    g.addColorStop(0.6, color + '33');
    g.addColorStop(1, color + '00');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);
    return finish(c, { repeat: [1, 1], srgb: true });
  });
}

