/* ============================================================
   Sim character built from primitives.
   ============================================================ */
export function createSim({ shirt = '#4f9a8a', pants = '#2d3446', skin = '#e0b894', hair = '#2a1d16', dress = false, hat = false, scale = 1 } = {}) {
  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);

  const mat = (c, rough = 0.85) => new THREE.MeshStandardMaterial({ color: c, roughness: rough, metalness: 0.02 });
  const shirtMat = mat(shirt);
  const pantsMat = mat(pants);
  const skinMat = mat(skin, 0.95);
  const hairMat = mat(hair, 0.9);

  const shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.28, depthWrite: false });
  const shadow = new THREE.Mesh(new THREE.CircleGeometry(0.42, 16), shadowMat);
  shadow.rotation.x = -Math.PI / 2; shadow.position.y = 0.012;
  group.add(shadow);

  const legGeo = new THREE.BoxGeometry(0.19, 0.62, 0.22);
  const legL = new THREE.Group(); legL.position.set(-0.14, 0.7, 0);
  const legR = new THREE.Group(); legR.position.set(0.14, 0.7, 0);
  for (const [leg, x] of [[legL, -0.14], [legR, 0.14]]) {
    const m = new THREE.Mesh(legGeo, pantsMat); m.position.y = -0.31; leg.add(m);
    const shoe = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.32), mat('#1c1a1e')); shoe.position.set(0, -0.61, 0.05); leg.add(shoe);
    body.add(leg);
  }

  if (dress) {
    const skirt = new THREE.Mesh(new THREE.CylinderGeometry(0.23, 0.42, 0.9, 8), shirtMat);
    skirt.position.y = 0.88; body.add(skirt);
  }
  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.66, 0.3), shirtMat);
  torso.position.y = 1.16; body.add(torso);
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.12, 6), skinMat); neck.position.y = 1.53; body.add(neck);

  const head = new THREE.Group(); head.position.y = 1.72; body.add(head);
  const face = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.34, 0.3), skinMat); head.add(face);
  const hairCap = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.16, 0.33), hairMat); hairCap.position.y = 0.13; head.add(hairCap);
  const hairBack = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.16, 0.08), hairMat); hairBack.position.set(0, 0.03, -0.16); head.add(hairBack);
  if (dress) {
    const bun = new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 6), hairMat); bun.position.set(0, 0.14, -0.2); head.add(bun);
  }
  if (hat) {
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.04, 16), hairMat); brim.position.y = 0.22; head.add(brim);
    const crown = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.22, 0.22, 12), hairMat); crown.position.y = 0.33; head.add(crown);
  }
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x16100d });
  for (const x of [-0.08, 0.08]) {
    const eye = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.055, 0.02), eyeMat);
    eye.position.set(x, 0.02, 0.156); head.add(eye);
  }

  const armGeo = new THREE.BoxGeometry(0.15, 0.55, 0.17);
  const armL = new THREE.Group(); armL.position.set(-0.35, 1.4, 0);
  const armR = new THREE.Group(); armR.position.set(0.35, 1.4, 0);
  for (const [arm, x] of [[armL, -0.35], [armR, 0.35]]) {
    const a = new THREE.Mesh(armGeo, dress ? shirtMat : skinMat); a.position.y = -0.27; arm.add(a);
    const hand = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.13, 0.18), skinMat); hand.position.y = -0.57; arm.add(hand);
    body.add(arm);
  }

  const plumbGeo = new THREE.OctahedronGeometry(0.19, 0);
  const plumbMat = new THREE.MeshStandardMaterial({
    color: 0x8bff5a, emissive: 0x3ddb2a, emissiveIntensity: 1.6, roughness: 0.3, metalness: 0.1,
  });
  const plumbob = new THREE.Mesh(plumbGeo, plumbMat);
  plumbob.position.y = 2.22; plumbob.scale.y = 1.5;
  group.add(plumbob);
  const plumbGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTexture('#8bff5a'), color: 0x9dff6a, transparent: true, opacity: 0.5,
    blending: THREE.AdditiveBlending, depthWrite: false,
  }));
  plumbGlow.scale.set(0.85, 0.85, 1); plumbGlow.position.y = 2.22; group.add(plumbGlow);

  group.scale.setScalar(scale);
  let phase = 0;
  return {
    group, plumbob,
    update(dt, moving = false, speed = 1) {
      phase += dt * (moving ? 9.5 * Math.min(1.4, speed) : 2);
      const swing = moving ? Math.sin(phase) * 0.62 : Math.sin(phase) * 0.04;
      legL.rotation.x = swing; legR.rotation.x = -swing;
      armL.rotation.x = -swing * 0.8; armR.rotation.x = swing * 0.8;
      body.position.y = moving ? Math.abs(Math.sin(phase)) * 0.045 : Math.sin(phase) * 0.012;
      plumbob.rotation.y += dt * 2.4;
      plumbob.position.y = 2.22 + Math.sin(phase * 0.5) * 0.05;
      plumbGlow.position.y = plumbob.position.y;
    },
  };
}

/* ============================================================
   Helpers
   ============================================================ */
function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.85, metalness: 0.02, ...opts });
}
function basic(color, opts = {}) {
  return new THREE.MeshBasicMaterial({ color, ...opts });
}

function mesh(geo, material, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, material);
  m.position.set(x, y, z);
  return m;
}

function gableRoof(w, d, eave, peak, material) {
  const geo = new THREE.BufferGeometry();
  const hw = w / 2, hd = d / 2;
  const positions = [
    // front slope
    -hw, eave, hd,  hw, eave, hd,  hw, peak, 0,
    -hw, eave, hd,  hw, peak, 0,  -hw, peak, 0,
    // back slope
    hw, eave, -hd,  -hw, eave, -hd,  -hw, peak, 0,
    hw, eave, -hd,  -hw, peak, 0,  hw, peak, 0,
    // gable left
    -hw, eave, -hd,  -hw, eave, hd,  -hw, peak, 0,
    // gable right
    hw, eave, hd,  hw, eave, -hd,  hw, peak, 0,
  ];
  const uvs = [];
  for (let i = 0; i < positions.length; i += 3) {
    uvs.push((positions[i] + hw) / w, (positions[i + 2] + hd) / d);
  }
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.computeVertexNormals();
  const m = new THREE.Mesh(geo, material);
  m.material.side = THREE.DoubleSide;
  return m;
}

/* ============================================================
   The neighborhood
   ============================================================ */
export class Neighborhood {
  constructor(scene) {
    this.scene = scene;
    this.group = new THREE.Group();
    scene.add(this.group);
    this.colliders = [];
    this.houses = [];
    this.markers = [];
    this.clouds = [];
    this.smoke = [];
    this.lamps = [];
    this.time = 0;
    this.npcMarker = null;
    this.cleared = new Set();
    this.modelUnlocked = false;
    this.build();
  }

  build() {
    const scene = this.scene;
    scene.background = new THREE.Color(0x2a1d31);
    scene.fog = new THREE.Fog(0x3a2530, 46, 122);

    this.hemi = new THREE.HemisphereLight(0xffd2b0, 0x2c3320, 1.15);
    scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight(0xffa768, 2.1);
    this.sun.position.set(-30, 42, 24);
    scene.add(this.sun);
    this.fill = new THREE.DirectionalLight(0x6f86c9, 0.5);
    this.fill.position.set(24, 18, -30);
    scene.add(this.fill);
    scene.add(new THREE.AmbientLight(0x4a3648, 0.55));

    this.buildSky();
    this.buildGround();
    this.buildRoad();
    this.buildIsland();
    this.buildHouses();
    this.buildProps();
    this.buildNpc();
    this.buildTrees();
    this.setProgress(new Set(), false);
  }

  buildSky() {
    const geo = new THREE.SphereGeometry(150, 32, 16);
    this.skyUniforms = {
      top: { value: new THREE.Color(0x241736) },
      bottom: { value: new THREE.Color(0xff8b54) },
      offset: { value: 0.12 },
    };
    const mat = new THREE.ShaderMaterial({
      uniforms: this.skyUniforms,
      side: THREE.BackSide, depthWrite: false, fog: false,
      vertexShader: `
        varying vec3 vWorld;
        void main() {
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }`,
      fragmentShader: `
        uniform vec3 top; uniform vec3 bottom; uniform float offset;
        varying vec3 vWorld;
        void main() {
          float h = normalize(vWorld).y;
          float t = pow(clamp((h + offset) / (1.0 + offset), 0.0, 1.0), 0.62);
          vec3 col = mix(bottom, top, t);
          gl_FragColor = vec4(col, 1.0);
        }`,
    });
    this.sky = new THREE.Mesh(geo, mat);
    this.group.add(this.sky);

    this.sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('#ffd0a0'), color: 0xffc08a, transparent: true, opacity: 0.85,
      blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
    }));
    this.sunSprite.scale.set(46, 46, 1);
    this.sunSprite.position.set(-58, 34, 88);
    this.group.add(this.sunSprite);

    for (let i = 0; i < 12; i++) {
      const sp = new THREE.Sprite(new THREE.SpriteMaterial({
        map: cloudTexture(), color: 0xffcfb0, transparent: true, opacity: 0.5,
        depthWrite: false, fog: false,
      }));
      const a = (i / 12) * Math.PI * 2 + Math.random() * 0.4;
      const r = 55 + Math.random() * 35;
      sp.position.set(Math.cos(a) * r, 26 + Math.random() * 16, Math.sin(a) * r);
      sp.scale.set(34 + Math.random() * 26, 16 + Math.random() * 10, 1);
      sp.userData.speed = 0.25 + Math.random() * 0.4;
      this.clouds.push(sp); this.group.add(sp);
    }

    // distant hills
    const hillMat = new THREE.MeshBasicMaterial({ color: 0x201a28, fog: true });
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * Math.PI * 2;
      const r = 92 + Math.random() * 20;
      const h = 6 + Math.random() * 10;
      const hill = new THREE.Mesh(new THREE.ConeGeometry(16 + Math.random() * 12, h, 5), hillMat);
      hill.position.set(Math.cos(a) * r, h / 2 - 1, Math.sin(a) * r);
      hill.rotation.y = Math.random() * 3;
      this.group.add(hill);
    }
  }

  buildGround() {
    const g = new THREE.Mesh(new THREE.PlaneGeometry(180, 180), new THREE.MeshStandardMaterial({
      map: grassTexture(), roughness: 1, color: 0x9aa77e,
    }));
    g.rotation.x = -Math.PI / 2;
    this.group.add(g);

    // subtle darker lot ground circles
    for (const h of HOUSE_LIST) {
      const a = this.houseAngle(h.id);
      const r = 23;
      const lot = new THREE.Mesh(new THREE.CircleGeometry(8.2, 32), new THREE.MeshStandardMaterial({
        map: grassTexture(), color: h.id === 'model' ? 0x6f6a58 : 0x8a9a6d, roughness: 1,
      }));
      lot.rotation.x = -Math.PI / 2;
      lot.position.set(Math.sin(a) * r, 0.012, Math.cos(a) * r);
      this.group.add(lot);
    }
  }

  houseAngle(id) {
    const idx = HOUSE_LIST.findIndex((h) => h.id === id);
    return (idx / HOUSE_LIST.length) * Math.PI * 2;
  }

  buildRoad() {
    const ring = new THREE.Mesh(new THREE.RingGeometry(10.4, 15.2, 72, 1), new THREE.MeshStandardMaterial({
      map: asphaltTexture(), color: 0x8f8f96, roughness: 1,
    }));
    ring.rotation.x = -Math.PI / 2; ring.position.y = 0.02;
    this.group.add(ring);

    const walk = new THREE.Mesh(new THREE.RingGeometry(15.2, 16.7, 72, 1), new THREE.MeshStandardMaterial({
      map: sidewalkTexture(), color: 0xb5afa0, roughness: 1,
    }));
    walk.rotation.x = -Math.PI / 2; walk.position.y = 0.016;
    this.group.add(walk);

    // dashed center line
    const dashMat = new THREE.MeshBasicMaterial({ color: 0xd8c98f });
    for (let i = 0; i < 40; i++) {
      const a = (i / 40) * Math.PI * 2;
      const dash = mesh(new THREE.BoxGeometry(0.14, 0.01, 1.1), dashMat, Math.sin(a) * 12.8, 0.032, Math.cos(a) * 12.8);
      dash.rotation.y = a;
      this.group.add(dash);
    }

    // driveways + walkways per house
    for (const h of HOUSE_LIST) {
      const a = this.houseAngle(h.id);
      const dir = new THREE.Vector3(-Math.sin(a), 0, -Math.cos(a));
      const drive = mesh(new THREE.PlaneGeometry(4.6, 3.4), new THREE.MeshStandardMaterial({
        map: concreteTexture('#8f8a7e'), color: 0x9d9a8e, roughness: 1,
      }), Math.sin(a) * 17.2, 0.026, Math.cos(a) * 17.2);
      drive.rotation.x = -Math.PI / 2; drive.rotation.z = -a;
      this.group.add(drive);
      const walkway = mesh(new THREE.PlaneGeometry(1.4, 2.2), new THREE.MeshStandardMaterial({
        map: sidewalkTexture(), color: 0xaaa494, roughness: 1,
      }), Math.sin(a) * 19.6, 0.028, Math.cos(a) * 19.6);
      walkway.rotation.x = -Math.PI / 2; walkway.rotation.z = -a;
      this.group.add(walkway);
    }
  }

  buildIsland() {
    const curb = new THREE.Mesh(new THREE.CylinderGeometry(10.35, 10.55, 0.28, 48), new THREE.MeshStandardMaterial({
      map: concreteTexture('#8a8578'), color: 0xa9a294, roughness: 1,
    }));
    curb.position.y = 0.14;
    this.group.add(curb);
    const lawn = new THREE.Mesh(new THREE.CircleGeometry(10.2, 48), new THREE.MeshStandardMaterial({
      map: grassTexture(), color: 0x93a577, roughness: 1,
    }));
    lawn.rotation.x = -Math.PI / 2; lawn.position.y = 0.29;
    this.group.add(lawn);

    // monument sign
    const signGroup = new THREE.Group();
    signGroup.position.set(0, 0, 0.4);
    const base = mesh(new THREE.BoxGeometry(5.4, 0.5, 0.9), new THREE.MeshStandardMaterial({
      map: brickTexture('#6a5d4d', '#8b8271'), roughness: 1,
    }), 0, 0.55, 0);
    signGroup.add(base);
    const board = mesh(new THREE.BoxGeometry(4.9, 1.5, 0.24), mat('#20301f'), 0, 1.55, 0);
    signGroup.add(board);
    const face = mesh(new THREE.PlaneGeometry(4.5, 1.24), new THREE.MeshBasicMaterial({
      map: signTexture({ lines: ['WHISPERING PINES'], bg: '#1d2c20', fg: '#f0e8d3', accent: '#c9a34e', size: 30, sub: 'EST. 1974 · POP. 0 · HOA ACTIVE' }),
    }), 0, 1.55, 0.13);
    signGroup.add(face);
    for (const x of [-2.1, 2.1]) {
      const post = mesh(new THREE.BoxGeometry(0.18, 1.5, 0.18), mat('#3a2a1e'), x, 0.75, -0.2);
      signGroup.add(post);
    }
    this.group.add(signGroup);
    this.colliders.push({ kind: 'box', x: 0, z: 0.4, hw: 2.7, hd: 0.6, rot: 0 });

    // benches
    for (const side of [-1, 1]) {
      const b = new THREE.Group();
      const seat = mesh(new THREE.BoxGeometry(2.2, 0.16, 0.6), mat('#6a4a30'), 0, 0.55, 0); b.add(seat);
      const back = mesh(new THREE.BoxGeometry(2.2, 0.55, 0.14), mat('#6a4a30'), 0, 0.86, -0.26); b.add(back);
      for (const x of [-0.85, 0.85]) { const leg = mesh(new THREE.BoxGeometry(0.12, 0.55, 0.5), mat('#2a2520'), x, 0.28, 0); b.add(leg); }
      b.position.set(side * 6.3, 0.29, 2.4); b.rotation.y = side * -0.7;
      this.group.add(b);
      this.colliders.push({ kind: 'box', x: b.position.x, z: b.position.z, hw: 1.2, hd: 0.4, rot: b.rotation.y });
    }

    // flower beds
    const flowerColors = [0xff7a8a, 0xffd36b, 0xc9a0ff];
    for (let i = 0; i < 18; i++) {
      const a = (i / 18) * Math.PI * 2;
      const r = 8.7 + Math.random() * 1.1;
      const stem = mesh(new THREE.CylinderGeometry(0.02, 0.03, 0.28, 4), mat('#3a5a28'), Math.sin(a) * r, 0.42, Math.cos(a) * r);
      this.group.add(stem);
      const bloom = mesh(new THREE.IcosahedronGeometry(0.09, 0), basic(flowerColors[i % 3]), Math.sin(a) * r, 0.58, Math.cos(a) * r);
      this.group.add(bloom);
    }
  }

  buildHouse(config, index) {
    const a = this.houseAngle(config.id);
    const R = 23;
    const center = new THREE.Vector3(Math.sin(a) * R, 0, Math.cos(a) * R);
    const rot = a + Math.PI;
    const g = new THREE.Group();
    g.position.copy(center);
    g.rotation.y = rot;
    this.group.add(g);

    const isModel = config.style === 'model';
    const isModern = config.style === 'modern';
    const w = isModel ? 10.5 : 9.6;
    const d = isModel ? 8.2 : 7.2;
    const wallH = isModel ? 4.1 : 3.5;

    const siding = new THREE.MeshStandardMaterial({
      map: sidingTexture(config.color), color: 0xffffff, roughness: 0.92,
    });
    const foundation = new THREE.MeshStandardMaterial({
      map: brickTexture(isModel ? '#3a2e2c' : '#6d5b49', '#8a8070'), roughness: 1,
    });

    const found = mesh(new THREE.BoxGeometry(w + 0.35, 0.5, d + 0.35), foundation, 0, 0.25, 0);
    g.add(found);
    const body = mesh(new THREE.BoxGeometry(w, wallH, d), siding, 0, 0.5 + wallH / 2, 0);
    g.add(body);

    // trim
    const trimMat = mat(isModern ? '#3a3a40' : '#d8d1bd', { roughness: 0.8 });
    const trim = mesh(new THREE.BoxGeometry(w + 0.12, 0.16, d + 0.12), trimMat, 0, 0.5 + 0.08, 0);
    g.add(trim);

    if (isModel) {
      const upper = mesh(new THREE.BoxGeometry(w * 0.66, 2.6, d * 0.62), siding, 0, 0.5 + wallH + 1.3, -0.4);
      g.add(upper);
      const roofSlab = mesh(new THREE.BoxGeometry(w * 0.7, 0.3, d * 0.66), mat('#1a1418'), 0, 0.5 + wallH + 2.65, -0.4);
      g.add(roofSlab);
      // tall windows on upper
      for (const x of [-1.6, 0, 1.6]) {
        const wm = new THREE.MeshBasicMaterial({ color: 0x4a1415 });
        const wm2 = new THREE.MeshBasicMaterial({ color: 0xffb347 });
        const win = mesh(new THREE.PlaneGeometry(0.7, 1.5), wm, x, 0.5 + wallH + 1.35, d * 0.31 - 0.38);
        g.add(win);
        const frame = mesh(new THREE.BoxGeometry(0.82, 1.62, 0.06), mat('#2a1a1c'), x, 0.5 + wallH + 1.35, d * 0.31 - 0.44);
        g.add(frame);
        win.position.z += 0.04;
      }
    }

    // roof
    const roofMat = new THREE.MeshStandardMaterial({ map: roofTexture(config.roof), color: 0xffffff, roughness: 0.95 });
    if (isModern) {
      const slab = mesh(new THREE.BoxGeometry(w + 1.1, 0.26, d + 1.1), roofMat, 0, 0.5 + wallH + 0.13, 0);
      g.add(slab);
      const parapet = mesh(new THREE.BoxGeometry(w + 1.2, 0.34, 0.3), mat('#2e3038'), 0, 0.5 + wallH + 0.38, d / 2 + 0.4);
      g.add(parapet);
      const parapet2 = parapet.clone(); parapet2.position.z = -d / 2 - 0.4; g.add(parapet2);
    } else if (!isModel) {
      const roof = gableRoof(w + 1.2, d + 1.2, 0.5 + wallH, 0.5 + wallH + 1.9, roofMat);
      g.add(roof);
      const ridge = mesh(new THREE.CylinderGeometry(0.1, 0.1, w + 1.4, 6), mat('#2a2020'), 0, 0.5 + wallH + 1.9, 0);
      ridge.rotation.z = Math.PI / 2; g.add(ridge);
    }

    // chimney
    if (!isModern) {
      const chimney = mesh(new THREE.BoxGeometry(0.8, 2.0, 0.8), foundation, w * 0.28, 0.5 + wallH + 0.9, -d * 0.18);
      g.add(chimney);
      const cap = mesh(new THREE.BoxGeometry(0.95, 0.14, 0.95), mat('#3a2c26'), w * 0.28, 0.5 + wallH + 1.95, -d * 0.18);
      g.add(cap);
    }

    // door
    const doorMat = new THREE.MeshStandardMaterial({ map: null, color: 0x3a2a20, roughness: 0.7, metalness: 0.15 });
    const door = mesh(new THREE.BoxGeometry(1.25, 2.35, 0.12), doorMat, 0, 1.18, d / 2 + 0.06);
    door.material.color.set(config.accent);
    door.material.color.multiplyScalar(0.5);
    g.add(door);
    const doorFrame = mesh(new THREE.BoxGeometry(1.55, 2.6, 0.16), trimMat, 0, 1.3, d / 2 + 0.01);
    g.add(doorFrame);
    door.renderOrder = 1;
    // door handle
    const handle = mesh(new THREE.SphereGeometry(0.055, 8, 6), mat('#d8b15a', { metalness: 0.6, roughness: 0.3 }), 0.42, 1.15, d / 2 + 0.14);
    g.add(handle);

    // porch
    const porch = mesh(new THREE.BoxGeometry(3.2, 0.18, 1.5), foundation, 0, 0.12, d / 2 + 0.7);
    g.add(porch);
    const step = mesh(new THREE.BoxGeometry(2.4, 0.12, 0.5), foundation, 0, 0.06, d / 2 + 1.65);
    g.add(step);
    if (!isModern) {
      for (const x of [-1.4, 1.4]) {
        const post = mesh(new THREE.BoxGeometry(0.14, 2.5, 0.14), trimMat, x, 1.3, d / 2 + 1.3);
        g.add(post);
      }
      const porchRoof = gableRoof(3.6, 2.0, 0.5 + 2.4, 0.5 + 2.9, roofMat);
      porchRoof.position.z = d / 2 + 0.55;
      g.add(porchRoof);
    }

    // windows
    const windowMats = [];
    const glowSprites = [];
    const addWindow = (x, y, z, ry, sw = 1.55, sh = 1.25) => {
      const wm = new THREE.MeshBasicMaterial({ color: 0x6a1a16 });
      windowMats.push(wm);
      const pane = mesh(new THREE.PlaneGeometry(sw, sh), wm, x, y, z);
      pane.rotation.y = ry;
      g.add(pane);
      const frame = mesh(new THREE.BoxGeometry(sw + 0.18, sh + 0.18, 0.08), trimMat, x, y, z - 0.02);
      frame.rotation.y = ry;
      g.add(frame);
      // mullions
      const mv = mesh(new THREE.BoxGeometry(0.08, sh, 0.07), trimMat, x, y, z + 0.02);
      mv.rotation.y = ry; g.add(mv);
      const mh = mesh(new THREE.BoxGeometry(sw, 0.07, 0.07), trimMat, x, y, z + 0.02);
      mh.rotation.y = ry; g.add(mh);
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture('#ff5a3a'), color: 0xff5a3a, transparent: true, opacity: 0.5,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      glow.scale.set(2.2, 1.9, 1);
      glow.position.set(x + Math.sin(ry) * 0.1, y, z + Math.cos(ry) * 0.1);
      g.add(glow);
      glowSprites.push(glow);
    };
    addWindow(-2.6, 2.15, d / 2 + 0.045, 0, 1.5, 1.2);
    addWindow(2.6, 2.15, d / 2 + 0.045, 0, 1.5, 1.2);
    addWindow(w / 2 + 0.045, 2.1, 0.6, Math.PI / 2, 1.5, 1.2);
    addWindow(-w / 2 - 0.045, 2.1, -1.2, Math.PI / 2, 1.3, 1.15);

    // house number plaque
    const plaque = mesh(new THREE.PlaneGeometry(0.75, 0.3), new THREE.MeshBasicMaterial({
      map: labelTexture(config.address.split(' ')[0], { fg: '#e8dcc0', size: 40 }),
      transparent: true,
    }), 1.55, 2.65, d / 2 + 0.08);
    g.add(plaque);

    // lawn sign
    const signGroup = new THREE.Group();
    signGroup.position.set(-3.6, 0, d / 2 + 2.9);
    const post = mesh(new THREE.BoxGeometry(0.1, 1.15, 0.1), mat('#3a2a1e'), 0, 0.575, 0);
    signGroup.add(post);
    const signMesh = mesh(new THREE.PlaneGeometry(2.55, 1.05), new THREE.MeshBasicMaterial({
      map: signTexture({ lines: ['OPEN HOUSE'], bg: '#1c2b1f', fg: '#f0e8d3', accent: '#ffb347', size: 34, sub: 'SERIOUSLY. COME IN.' }),
      side: THREE.DoubleSide,
    }), 0, 1.42, 0);
    signGroup.add(signMesh);
    g.add(signGroup);

    // mailbox
    const mail = new THREE.Group();
    mail.position.set(3.5, 0, d / 2 + 2.4);
    const mpost = mesh(new THREE.BoxGeometry(0.1, 1.1, 0.1), mat('#4a3a2a'), 0, 0.55, 0); mail.add(mpost);
    const mbox = mesh(new THREE.BoxGeometry(0.42, 0.32, 0.62), mat('#3a3a40', { metalness: 0.3 }), 0, 1.2, 0); mail.add(mbox);
    const flag = mesh(new THREE.BoxGeometry(0.04, 0.3, 0.06), basic('#c93a2a'), 0.24, 1.32, 0); mail.add(flag);
    g.add(mail);

    // flamingo
    if (!isModel) {
      const fl = new THREE.Group();
      fl.position.set(3.8, 0, d / 2 + 3.6);
      const bodyF = mesh(new THREE.SphereGeometry(0.22, 8, 6), basic('#ff8fa3'), 0, 0.72, 0);
      bodyF.scale.set(0.8, 1.2, 0.7); fl.add(bodyF);
      const neck = mesh(new THREE.CylinderGeometry(0.04, 0.05, 0.6, 5), basic('#ff8fa3'), 0.1, 1.0, 0);
      neck.rotation.z = -0.4; fl.add(neck);
      const headF = mesh(new THREE.SphereGeometry(0.1, 8, 6), basic('#ff8fa3'), 0.22, 1.3, 0); fl.add(headF);
      const beak = mesh(new THREE.ConeGeometry(0.05, 0.18, 4), basic('#2a2520'), 0.32, 1.29, 0);
      beak.rotation.z = -Math.PI / 2; fl.add(beak);
      for (const x of [-0.05, 0.05]) {
        const leg = mesh(new THREE.CylinderGeometry(0.015, 0.015, 0.55, 4), basic('#3a3a40'), x, 0.3, 0);
        fl.add(leg);
      }
      fl.rotation.y = -0.4;
      g.add(fl);
    }

    // hedges
    const hedgeMat = new THREE.MeshStandardMaterial({ map: hedgeTexture(), color: 0x6f8a4e, roughness: 1 });
    if (!isModern) {
      for (const x of [-w / 2 - 1.3, w / 2 + 1.3]) {
        const hedge = mesh(new THREE.BoxGeometry(1.2, 1.15, 5.5), hedgeMat, x, 0.58, -1.5);
        g.add(hedge);
      }
    }

    // banner for model home
    if (isModel) {
      const banner = mesh(new THREE.PlaneGeometry(3.2, 0.7), new THREE.MeshBasicMaterial({
        map: signTexture({ lines: ['THE MODEL HOME'], bg: '#2a1214', fg: '#ffd9a1', accent: '#ffb347', size: 30, sub: 'BY APPOINTMENT ONLY' }),
        side: THREE.DoubleSide,
      }), 0, 3.1, d / 2 + 1.35);
      g.add(banner);
    }

    // door glow sprite
    const doorGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('#ff5a3a'), color: 0xff4a2a, transparent: true, opacity: 0.7,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    doorGlow.scale.set(2.6, 2.6, 1);
    doorGlow.position.set(0, 1.8, d / 2 + 0.5);
    g.add(doorGlow);

    // chimney smoke
    const smokeSprites = [];
    for (let i = 0; i < 5; i++) {
      const sp = new THREE.Sprite(new THREE.SpriteMaterial({
        map: smokeTexture(), color: 0x6f6466, transparent: true, opacity: 0.0,
        depthWrite: false,
      }));
      sp.position.set(w * 0.28, 0.5 + wallH + 2.1 + i * 0.7, -d * 0.18);
      sp.userData.phase = i * 0.6;
      sp.scale.set(1.2 + i * 0.5, 1.2 + i * 0.5, 1);
      g.add(sp); smokeSprites.push(sp);
    }

    // collider (oriented box)
    this.colliders.push({ kind: 'box', x: center.x, z: center.z, hw: w / 2 + 0.35, hd: d / 2 + 1.0, rot });

    // marker
    const marker = document.createElement('div');
    marker.className = 'marker';
    marker.innerHTML = `<div class="mk-pin"></div><div class="mk-line"></div>`;
    document.getElementById('markers').appendChild(marker);

    const dir = new THREE.Vector3(-Math.sin(a), 0, -Math.cos(a));
    const doorWorld = new THREE.Vector3(center.x + dir.x * (d / 2 + 0.2), 0, center.z + dir.z * (d / 2 + 0.2));
    const entrance = new THREE.Vector3(center.x + dir.x * (d / 2 + 1.9), 0, center.z + dir.z * (d / 2 + 1.9));

    const house = {
      config, index, group: g, center, angle: a, rot, marker, doorWorld, entrance,
      windowMats, glowSprites, doorGlow, smokeSprites, signMesh, signGroup,
      collider: this.colliders[this.colliders.length - 1],
      cleared: false, locked: config.id === 'model',
      bodyHeight: wallH, width: w, depth: d,
    };
    this.houses.push(house);

    // smoke base positions
    smokeSprites.forEach((sp) => {
      sp.userData.baseY = sp.position.y;
      sp.userData.baseX = sp.position.x;
      sp.userData.baseZ = sp.position.z;
      this.smoke.push(sp);
    });

    return house;
  }

  buildHouses() {
    HOUSE_LIST.forEach((h, i) => this.buildHouse(h, i));
  }

  buildNpc() {
    this.npc = createSim({ shirt: '#1e1a26', pants: '#1e1a26', skin: '#cfd2c2', hair: '#6a6672', dress: true, hat: true, scale: 1.02 });
    this.npc.group.position.set(-3.4, 0.3, 7.4);
    this.npc.group.rotation.y = 2.0;
    this.group.add(this.npc.group);

    const bubble = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('#ffb347'), color: 0xffb347, transparent: true, opacity: 0.55,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    bubble.scale.set(1.1, 1.1, 1); bubble.position.y = 2.8;
    this.npc.group.add(bubble);
    this.npcBubble = bubble;

    this.npcMarker = document.createElement('div');
    this.npcMarker.className = 'marker npc';
    this.npcMarker.innerHTML = `<div class="mk-pin"><b>◆</b> MORTICIA · REALTOR</div>`;
    document.getElementById('markers').appendChild(this.npcMarker);
    this.markers.push(this.npcMarker);
  }

  buildTrees() {
    const leafMats = [0x2f4a25, 0x39562b, 0x2a3f22].map((c) => mat(c, { roughness: 1 }));
    const trunkMat = mat('#4a3626', { roughness: 1 });
    const positions = [];
    for (let i = 0; i < 22; i++) {
      const a = (i / 22) * Math.PI * 2 + (Math.random() - 0.5) * 0.16;
      const r = 30 + Math.random() * 14;
      if (Math.abs(a) < 0.02) continue;
      positions.push([Math.sin(a) * r, Math.cos(a) * r]);
    }
    positions.push([-9, 30], [9, 33], [-28, -12], [27, -8], [-15, -24], [16, -27]);

    for (const [x, z] of positions) {
      const s = 0.8 + Math.random() * 0.8;
      const tree = new THREE.Group();
      tree.position.set(x, 0, z);
      const trunk = mesh(new THREE.CylinderGeometry(0.22 * s, 0.35 * s, 2.6 * s, 6), trunkMat, 0, 1.3 * s, 0);
      tree.add(trunk);
      const dead = Math.random() < 0.22;
      if (dead) {
        for (let i = 0; i < 4; i++) {
          const branch = mesh(new THREE.CylinderGeometry(0.06 * s, 0.12 * s, 1.6 * s, 4), trunkMat, 0, 2.4 * s, 0);
          branch.rotation.z = (Math.random() - 0.5) * 1.8; branch.rotation.y = Math.random() * 3;
          branch.position.x = (Math.random() - 0.5) * 0.5 * s;
          tree.add(branch);
        }
      } else {
        for (let i = 0; i < 3; i++) {
          const foliage = mesh(new THREE.IcosahedronGeometry((1.35 - i * 0.22) * s, 0), leafMats[i % 3],
            (Math.random() - 0.5) * 0.6 * s, (2.6 + i * 0.85) * s, (Math.random() - 0.5) * 0.6 * s);
          foliage.rotation.set(Math.random(), Math.random(), Math.random());
          tree.add(foliage);
        }
      }
      this.group.add(tree);
      this.colliders.push({ kind: 'circle', x, z, r: 0.55 * s });
    }

    // lot shrubs
    const shrubMat = new THREE.MeshStandardMaterial({ map: hedgeTexture(), color: 0x5f7a45, roughness: 1 });
    for (const h of HOUSE_LIST) {
      const a = this.houseAngle(h.id);
      for (const off of [-5.8, 5.8]) {
        const bx = Math.sin(a) * 23 + Math.cos(a) * off;
        const bz = Math.cos(a) * 23 - Math.sin(a) * off;
        const shrub = mesh(new THREE.IcosahedronGeometry(0.8, 1), shrubMat, bx, 0.7, bz);
        shrub.scale.set(1, 0.8, 1);
        this.group.add(shrub);
      }
    }
  }

  buildProps() {
    // street lamps
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2 + 0.3;
      const x = Math.sin(a) * 15.9, z = Math.cos(a) * 15.9;
      const lamp = new THREE.Group();
      lamp.position.set(x, 0, z);
      lamp.userData.angle = a;
      const pole = mesh(new THREE.CylinderGeometry(0.09, 0.14, 4.6, 6), mat('#26282c', { metalness: 0.5, roughness: 0.5 }), 0, 2.3, 0);
      lamp.add(pole);
      const arm = mesh(new THREE.BoxGeometry(0.1, 0.1, 0.9), mat('#26282c'), 0, 4.55, -0.42);
      lamp.add(arm);
      const bulbMat = new THREE.MeshBasicMaterial({ color: 0xffc177 });
      const bulb = mesh(new THREE.SphereGeometry(0.22, 8, 6), bulbMat, 0, 4.5, -0.85);
      lamp.add(bulb);
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture('#ffb347'), color: 0xffb347, transparent: true, opacity: 0.8,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      glow.scale.set(4.5, 4.5, 1); glow.position.set(0, 4.5, -0.85);
      lamp.add(glow);
      lamp.rotation.y = a + Math.PI;
      this.group.add(lamp);
      this.lamps.push({ lamp, glow, bulbMat });
      this.colliders.push({ kind: 'circle', x, z, r: 0.35 });
    }

    // parked car
    const car = this.makeCar('#7a2d2a');
    car.position.set(Math.sin(0.9) * 17.9, 0.03, Math.cos(0.9) * 17.9);
    car.rotation.y = 0.9 + Math.PI + 0.1;
    this.group.add(car);
    this.colliders.push({ kind: 'box', x: car.position.x, z: car.position.z, hw: 1.15, hd: 2.2, rot: car.rotation.y });

    // hydrant
    const hyd = new THREE.Group();
    hyd.position.set(15.9, 0.02, -8.5);
    const hbody = mesh(new THREE.CylinderGeometry(0.16, 0.19, 0.55, 8), basic('#b23a2e'), 0, 0.3, 0); hyd.add(hbody);
    const htop = mesh(new THREE.SphereGeometry(0.17, 8, 6), basic('#c94737'), 0, 0.62, 0); hyd.add(htop);
    for (const x of [-0.2, 0.2]) { const nub = mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.18, 6), basic('#8f2a22'), x, 0.38, 0); nub.rotation.z = Math.PI / 2; hyd.add(nub); }
    this.group.add(hyd);

    // trash bins at a couple houses
    for (const idx of [1, 3]) {
      const h = HOUSE_LIST[idx]; const a = this.houseAngle(h.id);
      const bin = new THREE.Group();
      bin.position.set(Math.sin(a) * 18.6 + Math.cos(a) * 3.4, 0.02, Math.cos(a) * 18.6 - Math.sin(a) * 3.4);
      const b = mesh(new THREE.BoxGeometry(0.65, 0.95, 0.6), mat('#2f4a35'), 0, 0.5, 0); bin.add(b);
      const lid = mesh(new THREE.BoxGeometry(0.72, 0.1, 0.66), mat('#3a5a40'), 0, 1.0, 0); bin.add(lid);
      bin.rotation.y = a; this.group.add(bin);
    }

    // basketball hoop near one house
    const hoop = new THREE.Group();
    const ha = this.houseAngle('bunker');
    hoop.position.set(Math.sin(ha) * 17.4 + Math.cos(ha) * 3.6, 0, Math.cos(ha) * 17.4 - Math.sin(ha) * 3.6);
    hoop.rotation.y = ha + Math.PI;
    const hp = mesh(new THREE.CylinderGeometry(0.07, 0.09, 3.4, 6), mat('#3a3a40'), 0, 1.7, 0); hoop.add(hp);
    const board = mesh(new THREE.BoxGeometry(1.2, 0.75, 0.08), basic('#d8d2c0'), 0, 3.3, 0.2); hoop.add(board);
    const rim = mesh(new THREE.TorusGeometry(0.28, 0.03, 6, 12), basic('#e2542b'), 0, 3.05, 0.5); rim.rotation.x = Math.PI / 2; hoop.add(rim);
    this.group.add(hoop); this.colliders.push({ kind: 'circle', x: hoop.position.x, z: hoop.position.z, r: 0.3 });
  }

  makeCar(color) {
    const car = new THREE.Group();
    const bodyMat = mat(color, { roughness: 0.5, metalness: 0.35 });
    const glassMat = mat('#2a3038', { roughness: 0.2, metalness: 0.6 });
    const body = mesh(new THREE.BoxGeometry(2.1, 0.55, 4.2), bodyMat, 0, 0.62, 0); car.add(body);
    const cabin = mesh(new THREE.BoxGeometry(1.86, 0.6, 2.2), bodyMat, 0, 1.12, -0.15); car.add(cabin);
    const glass = mesh(new THREE.BoxGeometry(1.88, 0.42, 2.0), glassMat, 0, 1.16, -0.15); car.add(glass);
    const wheelMat = mat('#16161a');
    for (const x of [-1.02, 1.02]) for (const z of [-1.35, 1.35]) {
      const wheel = mesh(new THREE.CylinderGeometry(0.35, 0.35, 0.24, 10), wheelMat, x, 0.36, z);
      wheel.rotation.z = Math.PI / 2; car.add(wheel);
    }
    for (const x of [-0.65, 0.65]) {
      const light = mesh(new THREE.BoxGeometry(0.4, 0.16, 0.06), basic('#ffe0a0'), x, 0.67, 2.11); car.add(light);
    }
    return car;
  }

  /* ---------------- state ---------------- */
  setProgress(cleared, modelUnlocked) {
    this.cleared = new Set(cleared);
    this.modelUnlocked = modelUnlocked;
    for (const h of this.houses) {
      const isCleared = this.cleared.has(h.config.id);
      const locked = h.config.id === 'model' && !modelUnlocked;
      h.cleared = isCleared; h.locked = locked;
      this.refreshHouse(h);
    }
    this.refreshMood();
  }

  refreshHouse(h) {
    const cursed = !h.cleared;
    const winColor = h.locked ? 0x22242c : h.cleared ? 0xffca7a : 0x8a1f19;
    const glowColor = h.locked ? 0x3a4a5a : h.cleared ? 0xffc36b : 0xff4a2a;
    for (const wm of h.windowMats) wm.color.setHex(winColor);
    for (const sp of h.glowSprites) {
      sp.material.color.setHex(glowColor);
      sp.material.opacity = h.locked ? 0.12 : h.cleared ? 0.5 : 0.65;
    }
    h.doorGlow.material.color.setHex(glowColor);
    h.doorGlow.material.opacity = h.locked ? 0.1 : h.cleared ? 0.5 : 0.7;
    for (const sm of h.smokeSprites) sm.visible = cursed && !h.locked;

    let signArgs;
    if (h.locked) signArgs = { lines: ['MODEL HOME'], bg: '#191a1e', fg: '#8f8f96', accent: '#6f7784', size: 26, sub: 'CLEAR 4 PROPERTIES' };
    else if (h.cleared) signArgs = { lines: ['SOLD'], bg: '#1c2b1f', fg: '#dff5c0', accent: '#97d05a', size: 46, sub: 'DEMONS EVICTED' };
    else signArgs = { lines: ['OPEN HOUSE'], bg: '#2a1712', fg: '#f0e8d3', accent: '#ff7a4a', size: 30, sub: 'SERIOUSLY. COME IN.' };
    if (h.signMesh.material.map) h.signMesh.material.map.dispose();
    h.signMesh.material.map = signTexture(signArgs);
    h.signMesh.material.needsUpdate = true;

    h.marker.className = 'marker' + (h.cleared ? ' cleared' : h.locked ? ' locked' : '');
    const pin = h.marker.querySelector('.mk-pin');
    if (pin) {
      const status = h.cleared ? '<b>CLEARED</b>' : h.locked ? '<b>LOCKED</b>' : '<b>◆</b> OPEN';
      pin.innerHTML = `${status} · ${h.config.address}`;
    }
  }

  refreshMood() {
    const n = this.cleared.size;
    const t = n / 5;
    const top = new THREE.Color(0x241736).lerp(new THREE.Color(0x4f88b8), t);
    const bot = new THREE.Color(0xff7450).lerp(new THREE.Color(0xffd39b), t);
    this.skyUniforms.top.value.copy(top);
    this.skyUniforms.bottom.value.copy(bot);
    this.scene.fog.color.copy(bot).lerp(new THREE.Color(0x2a2030), 0.7);
    this.sun.color.copy(new THREE.Color(0xff9a5a).lerp(new THREE.Color(0xffdcae), t));
    this.sun.intensity = 2.1 + t * 0.7;
    this.hemi.intensity = 1.15 + t * 0.4;
    this.scene.background.copy(top);
    for (const sp of this.clouds) sp.material.color.copy(new THREE.Color(0xffb28a).lerp(new THREE.Color(0xffe9d2), t));
    for (const l of this.lamps) {
      l.bulbMat.color.copy(new THREE.Color(0xffb060).lerp(new THREE.Color(0xffe6b0), t));
      l.glow.material.color.copy(l.bulbMat.color);
    }
    if (this.npcBubble) this.npcBubble.material.opacity = n === 5 ? 0.9 : 0.55;
  }

  /* ---------------- per-frame ---------------- */
  update(dt, time) {
    this.time = time;
    for (const c of this.clouds) {
      c.position.x += c.userData.speed * dt;
      if (c.position.x > 95) c.position.x = -95;
    }
    for (const sp of this.smoke) {
      if (!sp.visible) continue;
      const ph = (time * 0.16 + sp.userData.phase) % 3.4;
      sp.position.y = sp.userData.baseY + ph * 1.3;
      sp.position.x = sp.userData.baseX + Math.sin(time * 0.5 + sp.userData.phase) * 0.35 + ph * 0.18;
      sp.position.z = sp.userData.baseZ + Math.cos(time * 0.4 + sp.userData.phase) * 0.3;
      sp.material.opacity = Math.max(0, 0.24 * (1 - ph / 3.4));
      sp.scale.setScalar(1.2 + ph * 0.52);
    }
    if (this.npc) {
      this.npc.update(dt, false, 0);
      this.npc.group.rotation.y += Math.sin(time * 0.35) * dt * 0.12;
      if (this.npcBubble) {
        this.npcBubble.position.y = 2.85 + Math.sin(time * 1.7) * 0.08;
        this.npcBubble.material.opacity = 0.4 + Math.sin(time * 2.2) * 0.15;
      }
    }
    for (const l of this.lamps) {
      l.glow.material.opacity = 0.7 + Math.sin(time * 3.1 + l.lamp.userData.angle * 5) * 0.06;
    }
    this.sunSprite.material.opacity = 0.8 + Math.sin(time * 0.4) * 0.05;
    this.sky.position.copy(this.scene.userData.cameraPos || new THREE.Vector3());
  }

  /* ---------------- interactions ---------------- */
  nearestInteraction(pos) {
    let best = null;
    for (const h of this.houses) {
      const d = pos.distanceTo(h.entrance);
      if (d < 2.9 && (!best || d < best.dist)) best = { type: 'house', house: h, dist: d };
    }
    const npcPos = this.npc.group.position;
    const nd = Math.hypot(pos.x - npcPos.x, pos.z - npcPos.z);
    if (nd < 2.6 && (!best || nd < best.dist)) best = { type: 'npc', dist: nd };
    return best;
  }

  updateMarkers(camera, w, h, pos) {
    const v = new THREE.Vector3();
    for (const h of this.houses) {
      if (!h.marker) continue;
      v.set(h.center.x, 7.6, h.center.z);
      const dist = pos.distanceTo(h.center);
      v.project(camera);
      const visible = v.z < 1 && v.x > -1.25 && v.x < 1.25 && v.y > -1.15 && v.y < 1.2 && dist < 70;
      h.marker.style.display = visible ? 'flex' : 'none';
      if (visible) {
        h.marker.style.left = `${(v.x * 0.5 + 0.5) * w}px`;
        h.marker.style.top = `${(-v.y * 0.5 + 0.5) * h}px`;
        h.marker.style.opacity = String(Math.max(0.35, 1 - dist / 85));
      }
    }
    if (this.npcMarker) {
      v.set(this.npc.group.position.x, 3.1, this.npc.group.position.z);
      const dist = pos.distanceTo(this.npc.group.position);
      v.project(camera);
      const visible = v.z < 1 && v.x > -1.2 && v.x < 1.2 && v.y > -1.1 && v.y < 1.2 && dist < 34;
      this.npcMarker.style.display = visible ? 'flex' : 'none';
      if (visible) {
        this.npcMarker.style.left = `${(v.x * 0.5 + 0.5) * w}px`;
        this.npcMarker.style.top = `${(-v.y * 0.5 + 0.5) * h}px`;
      }
    }
  }

  getSpawn() {
    return new THREE.Vector3(0, 0, 7.6);
  }
}

/* ============================================================
   Collision resolution shared by neighbourhood and level.
   ============================================================ */
export function resolveColliders(pos, radius, colliders) {
  for (const c of colliders) {
    if (c.kind === 'circle') {
      const dx = pos.x - c.x, dz = pos.z - c.z;
      const d = Math.hypot(dx, dz);
      const min = radius + c.r;
      if (d < min && d > 0.0001) {
        const push = (min - d);
        pos.x += (dx / d) * push;
        pos.z += (dz / d) * push;
      }
    } else if (c.kind === 'box') {
      const cos = Math.cos(c.rot), sin = Math.sin(c.rot);
      const dx = pos.x - c.x, dz = pos.z - c.z;
      const lx = dx * cos - dz * sin;
      const lz = dx * sin + dz * cos;
      const cx = Math.max(-c.hw, Math.min(c.hw, lx));
      const cz = Math.max(-c.hd, Math.min(c.hd, lz));
      let px = lx - cx, pz = lz - cz;
      const d = Math.hypot(px, pz);
      if (d < radius) {
        let pushX = 0, pushZ = 0;
        if (d > 0.0001) {
          const push = radius - d;
          pushX = (px / d) * push; pushZ = (pz / d) * push;
        } else {
          // inside the box: push out via nearest face
          const ox = c.hw - Math.abs(lx), oz = c.hd - Math.abs(lz);
          if (ox < oz) pushX = (lx >= 0 ? 1 : -1) * (ox + radius);
          else pushZ = (lz >= 0 ? 1 : -1) * (oz + radius);
        }
        pos.x += pushX * cos + pushZ * sin;
        pos.z += -pushX * sin + pushZ * cos;
      }
    }
  }
  return pos;
}

import * as THREE from 'three';
import {
  hellWallTexture, hellFloorTexture, ceilingTexture, doorTexture, metalTexture,
  bloodTexture, pentagramTexture, glowTexture, itemTexture, demonTexture,
  brickTexture, concreteTexture,
} from './textures.js';

const ROOM_NAMES = [
  'Foyer of False Hope', 'The Living Hell', 'Dining Room of Bones', 'Kitchen of Knives',
  'Master Bedchamber', 'Spa of Sorrows', 'The Rec Room', 'Laundry of Lost Souls',
  'Home Office of the Damned', 'Guest Room', 'The Walk-In Abyss', 'The Basement',
  'Sunroom of Screams', 'Hallway to Nowhere', 'Pantry of Pain', 'Nursery of Nightmares',
  'Mudroom of Regret', 'The Powder Room', 'Wine Cellar', 'Attic of Agony',
];

export const ENEMY_STATS = {
  zombie: { hp: 34, speed: 1.7, ranged: true, range: 17, cooldown: 2.15, dmg: 7, melee: false, sx: 1.35, sy: 1.75, y: 1.0, radius: 0.8, name: 'HOA VOLUNTEER' },
  imp: { hp: 46, speed: 1.95, ranged: true, range: 15, cooldown: 2.0, dmg: 13, melee: false, sx: 1.65, sy: 2.0, y: 1.15, radius: 0.85, name: 'IMP' },
  pinky: { hp: 92, speed: 2.95, ranged: false, range: 2.1, cooldown: 1.05, dmg: 16, melee: true, sx: 2.0, sy: 1.9, y: 1.05, radius: 0.95, name: 'PINKY' },
  boss: { hp: 720, speed: 1.45, ranged: true, range: 22, cooldown: 1.5, dmg: 19, melee: true, sx: 3.8, sy: 3.8, y: 1.9, radius: 1.85, name: 'THE HOA PRESIDENT' },
};

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export class Dungeon {
  constructor(config) {
    this.config = config;
    this.W = 35; this.H = 35;
    this.cell = 2.2;
    this.wallH = 3.0;
    this.grid = [];
    this.rooms = [];
    this.doors = [];
    this.items = [];
    this.enemies = [];
    this.colliders = [];
    this.torches = [];
    this.projectiles = [];
    this.visited = [];
    this.exit = null;
    this.spawn = null;
    this.keyRoom = null;
    this.exitRoom = null;
    this.startTime = 0;
    this.totalEnemies = 0;
    this.generate();
  }

  /* ---------------- generation ---------------- */
  generate() {
    const { W, H } = this;
    this.grid = Array.from({ length: H }, () => new Array(W).fill(1));
    this.visited = Array.from({ length: H }, () => new Array(W).fill(false));
    const rnd = Math.random;
    const leaves = [];

    const split = (node, depth) => {
      const minLeaf = 7;
      const canH = node.h >= minLeaf * 2;
      const canW = node.w >= minLeaf * 2;
      if (depth <= 0 || (!canH && !canW)) { leaves.push(node); return; }
      let horiz;
      if (canH && canW) {
        const ratio = node.h / node.w;
        horiz = ratio > 1.2 ? true : ratio < 0.83 ? false : rnd() < 0.5;
      } else horiz = canH;
      if (horiz) {
        const cut = minLeaf + Math.floor(rnd() * (node.h - minLeaf * 2 + 1));
        split({ x: node.x, z: node.z, w: node.w, h: cut }, depth - 1);
        split({ x: node.x, z: node.z + cut, w: node.w, h: node.h - cut }, depth - 1);
      } else {
        const cut = minLeaf + Math.floor(rnd() * (node.w - minLeaf * 2 + 1));
        split({ x: node.x, z: node.z, w: cut, h: node.h }, depth - 1);
        split({ x: node.x + cut, z: node.z, w: node.w - cut, h: node.h }, depth - 1);
      }
    };
    split({ x: 1, z: 1, w: W - 2, h: H - 2 }, 4);

    const names = shuffle([...ROOM_NAMES]);
    for (const leaf of leaves) {
      const margin = 1;
      const x = leaf.x + margin;
      const z = leaf.z + margin;
      const w = leaf.w - margin * 2;
      const h = leaf.h - margin * 2;
      if (w < 4 || h < 4) continue;
      const room = {
        x, z, w, h, leaf,
        cx: x + w / 2, cz: z + h / 2,
        label: names.pop() || 'The Void',
        nameIndex: this.rooms.length,
      };
      for (let zz = z; zz < z + h; zz++) for (let xx = x; xx < x + w; xx++) this.grid[zz][xx] = 0;
      this.rooms.push(room);
    }

    // Connect BSP leaves by walking the split tree again.
    const connect = (node) => {
      if (!node.a) {
        const candidates = this.rooms.filter((r) => r.leaf === node);
        return candidates.length ? [candidates[0]] : [];
      }
      const left = connect(node.a);
      const right = connect(node.b);
      if (left.length && right.length) {
        const A = left[Math.floor(rnd() * left.length)];
        const B = right[Math.floor(rnd() * right.length)];
        this.carveCorridor(
          Math.floor(A.cx), Math.floor(A.cz),
          Math.floor(B.cx), Math.floor(B.cz)
        );
      }
      return left.concat(right);
    };

    // rebuild tree with references
    const buildTree = (node, depth) => {
      const minLeaf = 7;
      const canH = node.h >= minLeaf * 2;
      const canW = node.w >= minLeaf * 2;
      if (depth <= 0 || (!canH && !canW)) return node;
      let horiz;
      if (canH && canW) {
        const ratio = node.h / node.w;
        horiz = ratio > 1.2 ? true : ratio < 0.83 ? false : rnd() < 0.5;
      } else horiz = canH;
      if (horiz) {
        const cut = minLeaf + Math.floor(rnd() * (node.h - minLeaf * 2 + 1));
        node.a = buildTree({ x: node.x, z: node.z, w: node.w, h: cut }, depth - 1);
        node.b = buildTree({ x: node.x, z: node.z + cut, w: node.w, h: node.h - cut }, depth - 1);
      } else {
        const cut = minLeaf + Math.floor(rnd() * (node.w - minLeaf * 2 + 1));
        node.a = buildTree({ x: node.x, z: node.z, w: cut, h: node.h }, depth - 1);
        node.b = buildTree({ x: node.x + cut, z: node.z, w: node.w - cut, h: node.h }, depth - 1);
      }
      return node;
    };
    // The tree rebuilt above must match the carved leaves; use it only for connectivity.
    // Recompute by connecting every room in sequence to the nearest unconnected room instead,
    // which is simpler and guaranteed connected.
    const order = shuffle([...this.rooms]);
    const connected = [order[0]];
    const remaining = order.slice(1);
    while (remaining.length) {
      let bestI = 0, bestJ = 0, bestD = Infinity;
      for (let i = 0; i < connected.length; i++) {
        for (let j = 0; j < remaining.length; j++) {
          const d = Math.hypot(connected[i].cx - remaining[j].cx, connected[i].cz - remaining[j].cz);
          if (d < bestD) { bestD = d; bestI = i; bestJ = j; }
        }
      }
      const A = connected[bestI], B = remaining[bestJ];
      this.carveCorridor(Math.floor(A.cx), Math.floor(A.cz), Math.floor(B.cx), Math.floor(B.cz));
      connected.push(B); remaining.splice(bestJ, 1);
    }

    // spawn room = the one closest to the front (+z)
    this.rooms.sort((a, b) => b.cz - a.cz);
    const spawnRoom = this.rooms[0];
    this.spawnRoom = spawnRoom;
    this.spawn = this.cellCenter(Math.floor(spawnRoom.cx), Math.floor(spawnRoom.cz));

    // exit room = farthest from spawn; key room = next farthest
    const byDist = [...this.rooms].sort((a, b) =>
      Math.hypot(b.cx - spawnRoom.cx, b.cz - spawnRoom.cz) - Math.hypot(a.cx - spawnRoom.cx, a.cz - spawnRoom.cz));
    this.exitRoom = byDist[0] || spawnRoom;
    this.keyRoom = byDist[1] || spawnRoom;
    if (this.exitRoom === spawnRoom && this.rooms.length > 1) {
      this.exitRoom = this.rooms[this.rooms.length - 1];
      this.keyRoom = this.rooms[this.rooms.length - 2];
    }

    this.findDoors();

    // collect walkable cells for placement
    this.walkable = [];
    for (let z = 1; z < H - 1; z++) for (let x = 1; x < W - 1; x++) {
      if (this.grid[z][x] === 0 && !this.doorAt(x, z)) this.walkable.push({ x, z });
    }

    // place exit portal
    const ex = this.cellCenter(Math.floor(this.exitRoom.cx), Math.floor(this.exitRoom.cz));
    this.exit = { x: ex.x, z: ex.z, unlocked: false, cell: { x: Math.floor(this.exitRoom.cx), z: Math.floor(this.exitRoom.cz) } };

    // place key
    const kx = this.cellCenter(Math.floor(this.keyRoom.cx), Math.floor(this.keyRoom.cz));
    this.placeItem('key', kx.x + (Math.random() - 0.5) * 1.2, kx.z + (Math.random() - 0.5) * 1.2, true);

    // place useful stuff
    const roomPool = this.rooms.filter((r) => r !== spawnRoom);
    const pickRooms = shuffle([...roomPool]);
    const types = ['health', 'shells', 'armor', 'shells', 'health', 'chaingun', 'shells', 'health', 'armor'];
    types.forEach((type, i) => {
      const room = pickRooms[i % Math.max(1, pickRooms.length)] || this.rooms[0];
      const p = this.randomFloorInRoom(room);
      if (p) this.placeItem(type, p.x, p.z, type === 'chaingun');
    });

    // enemies
    this.placeEnemies(spawnRoom);

    // room props / torches
    this.placeProps();
    this.placeTorches();
  }

  carveCorridor(x1, z1, x2, z2) {
    const carve = (x, z) => {
      if (x > 0 && x < this.W - 1 && z > 0 && z < this.H - 1) {
        this.grid[z][x] = 0;
        this.grid[z][Math.min(this.W - 2, x + 1)] = 0;
        this.grid[Math.min(this.H - 2, z + 1)][x] = 0;
      }
    };
    let x = x1, z = z1;
    const horizFirst = Math.random() < 0.5;
    if (horizFirst) {
      while (x !== x2) { carve(x, z); x += Math.sign(x2 - x); }
      while (z !== z2) { carve(x, z); z += Math.sign(z2 - z); }
    } else {
      while (z !== z2) { carve(x, z); z += Math.sign(z2 - z); }
      while (x !== x2) { carve(x, z); x += Math.sign(x2 - x); }
    }
    carve(x2, z2);
  }

  findDoors() {
    const candidates = [];
    for (const room of this.rooms) {
      if (room === this.spawnRoom) continue;
      const sides = [];
      for (let z = room.z; z < room.z + room.h; z++) {
        sides.push({ x: room.x - 1, z, axis: 'z' });
        sides.push({ x: room.x + room.w, z, axis: 'z' });
      }
      for (let x = room.x; x < room.x + room.w; x++) {
        sides.push({ x, z: room.z - 1, axis: 'x' });
        sides.push({ x, z: room.z + room.h, axis: 'x' });
      }
      for (const s of sides) {
        const outside = s.axis === 'z'
          ? (s.x < room.x ? s.x - 1 : s.x + 1)
          : (s.z < room.z ? s.z - 1 : s.z + 1);
        const ok = s.axis === 'z'
          ? this.inBounds(outside, s.z) && this.grid[s.z][outside] === 0
          : this.inBounds(s.x, outside) && this.grid[outside][s.x] === 0;
        if (ok && this.inBounds(s.x, s.z) && this.grid[s.z][s.x] === 0 && !this.doorAt(s.x, s.z)) {
          candidates.push({ ...s, room });
        }
      }
    }
    shuffle(candidates);
    const chosen = candidates.slice(0, Math.min(5, Math.max(2, Math.floor(this.rooms.length / 2))));
    for (const c of chosen) {
      this.doors.push({
        cx: c.x, cz: c.z, axis: c.axis, room: c.room,
        open: false, progress: 0, mesh: null, panel: null,
      });
    }
  }

  placeEnemies(spawnRoom) {
    const { config } = this;
    const stats = ENEMY_STATS;
    const pool = config.demonTypes.filter((t) => t !== 'boss');
    const diff = config.difficulty;
    const hpMul = 1 + (diff - 1) * 0.16;
    const total = config.enemies;
    const rooms = this.rooms.filter((r) => r !== spawnRoom);
    const roomWeights = rooms.map((r) => r.w * r.h);
    const sum = roomWeights.reduce((a, b) => a + b, 0);
    const occupancy = [];

    const canPlace = (p, min = 3.0) => occupancy.every((o) => Math.hypot(o.x - p.x, o.z - p.z) > min);

    let placed = 0;
    let guard = 0;
    while (placed < total && guard++ < 3000) {
      let r = Math.random() * sum, idx = 0;
      for (; idx < rooms.length; idx++) { r -= roomWeights[idx]; if (r <= 0) break; }
      const room = rooms[Math.min(idx, rooms.length - 1)];
      const p = this.randomFloorInRoom(room, 0.25);
      if (!p) continue;
      if (Math.hypot(p.x - this.spawn.x, p.z - this.spawn.z) < 9) continue;
      if (!canPlace(p, 2.6)) continue;
      if (this.exit && Math.hypot(p.x - this.exit.x, p.z - this.exit.z) < 3.2) continue;
      const type = pool[Math.floor(Math.random() * pool.length)] || 'zombie';
      const st = stats[type];
      const hp = Math.round(st.hp * hpMul);
      this.enemies.push(this.makeEnemyData(type, p.x, p.z, hp, st));
      occupancy.push(p);
      placed++;
    }
    if (config.demonTypes.includes('boss')) {
      const p = this.cellCenter(Math.floor(this.exitRoom.cx), Math.floor(this.exitRoom.cz + 1.4));
      const st = stats.boss;
      this.enemies.push(this.makeEnemyData('boss', p.x, p.z, st.hp, st));
      occupancy.push(p);
    }
    this.totalEnemies = this.enemies.length;
  }

  makeEnemyData(type, x, z, hp, st) {
    return {
      type, x, z, spawnX: x, spawnZ: z, hp, maxHp: hp,
      speed: st.speed, ranged: st.ranged, range: st.range, cooldown: st.cooldown,
      dmg: st.dmg, melee: st.melee, sx: st.sx, sy: st.sy, y: st.y, radius: st.radius,
      state: 'idle', aggro: false, cool: Math.random() * st.cooldown,
      deathT: -1, hitFlash: 0, bob: Math.random() * 6, dead: false,
      sprite: null, glow: null, lunge: 0, growlT: 1 + Math.random() * 4,
    };
  }

  randomFloorInRoom(room, inset = 1) {
    for (let tries = 0; tries < 30; tries++) {
      const x = room.x + inset + Math.random() * (room.w - inset * 2);
      const z = room.z + inset + Math.random() * (room.h - inset * 2);
      const gx = Math.floor(x), gz = Math.floor(z);
      if (this.grid[gz] && this.grid[gz][gx] === 0 && !this.doorAt(gx, gz)) {
        const w = this.cellCenter(gx, gz);
        return { x: w.x + (Math.random() - 0.5) * 0.9, z: w.z + (Math.random() - 0.5) * 0.9 };
      }
    }
    const w = this.cellCenter(Math.floor(room.cx), Math.floor(room.cz));
    return w;
  }

  /* ---------------- geometry helpers ---------------- */
  inBounds(x, z) { return x >= 0 && z >= 0 && x < this.W && z < this.H; }
  cellCenter(gx, gz) {
    return {
      x: (gx - this.W / 2 + 0.5) * this.cell,
      z: (gz - this.H / 2 + 0.5) * this.cell,
    };
  }
  worldToCell(x, z) {
    return { x: Math.floor(x / this.cell + this.W / 2), z: Math.floor(z / this.cell + this.H / 2) };
  }
  doorAt(gx, gz) {
    return this.doors.find((d) => d.cx === gx && d.cz === gz) || null;
  }
  isSolidCell(gx, gz) {
    if (!this.inBounds(gx, gz)) return true;
    if (this.grid[gz][gx] === 1) return true;
    const d = this.doorAt(gx, gz);
    if (d && !d.open) return true;
    return false;
  }
  isSolidWorld(x, z) {
    const c = this.worldToCell(x, z);
    return this.isSolidCell(c.x, c.z);
  }

  /* ---------------- build meshes ---------------- */
  build(scene) {
    const t = this.config.theme;
    const group = new THREE.Group();
    this.group = group;
    scene.add(group);

    const floorTex = hellFloorTexture(t).clone();
    floorTex.needsUpdate = true;
    floorTex.repeat.set(this.W * 0.5, this.H * 0.5);
    const floorMat = new THREE.MeshStandardMaterial({ map: floorTex, color: 0xb9ac9c, roughness: 0.95 });
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(this.W * this.cell, this.H * this.cell), floorMat);
    floor.rotation.x = -Math.PI / 2;
    group.add(floor);

    const ceilTex = ceilingTexture(t).clone();
    ceilTex.needsUpdate = true;
    ceilTex.repeat.set(this.W * 0.4, this.H * 0.4);
    const ceilMat = new THREE.MeshStandardMaterial({ map: ceilTex, color: 0x8a8088, roughness: 1, side: THREE.DoubleSide });
    const ceil = new THREE.Mesh(new THREE.PlaneGeometry(this.W * this.cell, this.H * this.cell), ceilMat);
    ceil.rotation.x = Math.PI / 2;
    ceil.position.y = this.wallH;
    group.add(ceil);

    // walls
    const wallTex = hellWallTexture(t).clone();
    wallTex.needsUpdate = true;
    wallTex.repeat.set(1, 1);
    const wallMat = new THREE.MeshStandardMaterial({ map: wallTex, color: 0xc9c0b2, roughness: 0.94 });
    const wallCells = [];
    for (let z = 0; z < this.H; z++) for (let x = 0; x < this.W; x++) {
      if (this.grid[z][x] === 1) wallCells.push([x, z]);
    }
    const wallGeo = new THREE.BoxGeometry(this.cell, this.wallH, this.cell);
    const walls = new THREE.InstancedMesh(wallGeo, wallMat, wallCells.length);
    const m = new THREE.Matrix4();
    const col = new THREE.Color();
    wallCells.forEach(([x, z], i) => {
      const p = this.cellCenter(x, z);
      m.makeTranslation(p.x, this.wallH / 2, p.z);
      walls.setMatrixAt(i, m);
      const v = 0.86 + Math.random() * 0.24;
      col.setRGB(v, v * 0.96, v * 0.94);
      walls.setColorAt(i, col);
    });
    walls.instanceMatrix.needsUpdate = true;
    if (walls.instanceColor) walls.instanceColor.needsUpdate = true;
    group.add(walls);

    // baseboard trim along wall/floor edge (thin dark boxes)
    const trimMat = new THREE.MeshStandardMaterial({ color: 0x17120f, roughness: 0.9 });
    const trimCells = [];
    for (let z = 0; z < this.H; z++) for (let x = 0; x < this.W; x++) {
      if (this.grid[z][x] !== 0) continue;
      if (this.isSolidRaw(x - 1, z)) trimCells.push({ x, z, side: 'w' });
      if (this.isSolidRaw(x + 1, z)) trimCells.push({ x, z, side: 'e' });
      if (this.isSolidRaw(x, z - 1)) trimCells.push({ x, z, side: 'n' });
      if (this.isSolidRaw(x, z + 1)) trimCells.push({ x, z, side: 's' });
    }
    const trimGeo = new THREE.BoxGeometry(1, 1, 1);
    const trims = new THREE.InstancedMesh(trimGeo, trimMat, trimCells.length);
    trimCells.forEach((c, i) => {
      const p = this.cellCenter(c.x, c.z);
      const alongX = c.side === 'n' || c.side === 's';
      m.makeScale(alongX ? this.cell : 0.12, 0.24, alongX ? 0.12 : this.cell);
      m.setPosition(
        p.x + (c.side === 'w' ? -this.cell / 2 + 0.07 : c.side === 'e' ? this.cell / 2 - 0.07 : 0),
        0.12,
        p.z + (c.side === 'n' ? -this.cell / 2 + 0.07 : c.side === 's' ? this.cell / 2 - 0.07 : 0)
      );
      trims.setMatrixAt(i, m);
    });
    trims.instanceMatrix.needsUpdate = true;
    group.add(trims);

    this.buildDoors(group);
    this.buildProps(group);
    this.buildItems(group);
    this.buildEnemies(group);
    this.buildExit(group);
    this.buildLights(group);

    // blood + pentagrams
    for (let i = 0; i < 22; i++) {
      const cell = this.walkable[Math.floor(Math.random() * this.walkable.length)];
      if (!cell) continue;
      const p = this.cellCenter(cell.x, cell.z);
      const decal = new THREE.Mesh(new THREE.PlaneGeometry(1.4 + Math.random() * 1.8, 1.4 + Math.random() * 1.8), new THREE.MeshBasicMaterial({
        map: bloodTexture(), transparent: true, opacity: 0.5 + Math.random() * 0.4, depthWrite: false,
      }));
      decal.rotation.x = -Math.PI / 2;
      decal.rotation.z = Math.random() * Math.PI * 2;
      decal.position.set(p.x, 0.012 + Math.random() * 0.006, p.z);
      group.add(decal);
    }
    const penta = new THREE.Mesh(new THREE.PlaneGeometry(4.5, 4.5), new THREE.MeshBasicMaterial({
      map: pentagramTexture('#d33a2a'), transparent: true, opacity: 0.55, depthWrite: false,
    }));
    penta.rotation.x = -Math.PI / 2;
    const pc = this.cellCenter(Math.floor(this.exitRoom.cx), Math.floor(this.exitRoom.cz));
    penta.position.set(pc.x, 0.02, pc.z);
    group.add(penta);
    this.penta = penta;
    this.pentaSpin = 0;

    this.scene = scene;
    this.startTime = performance.now();
    return this;
  }

  isSolidRaw(x, z) {
    if (!this.inBounds(x, z)) return true;
    return this.grid[z][x] === 1;
  }

  buildDoors(group) {
    const tex = doorTexture(this.config.theme);
    const frameMat = new THREE.MeshStandardMaterial({ map: metalTexture('#3a3c40', '#17181b'), roughness: 0.55, metalness: 0.45 });
    const panelMat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.55, metalness: 0.25, color: 0xd8cdb8 });
    for (const d of this.doors) {
      const p = this.cellCenter(d.cx, d.cz);
      const g = new THREE.Group();
      g.position.set(p.x, 0, p.z);
      if (d.axis === 'x') g.rotation.y = 0; else g.rotation.y = Math.PI / 2;
      // frame
      const width = this.cell;
      for (const x of [-width / 2 + 0.1, width / 2 - 0.1]) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(0.16, 2.7, 0.5), frameMat);
        post.position.set(x, 1.35, 0);
        g.add(post);
      }
      const lintel = new THREE.Mesh(new THREE.BoxGeometry(width, 0.22, 0.5), frameMat);
      lintel.position.y = 2.7;
      g.add(lintel);
      // panel
      const panel = new THREE.Mesh(new THREE.BoxGeometry(width - 0.2, 2.5, 0.18), panelMat);
      panel.position.y = 1.25;
      g.add(panel);
      // warning light
      const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff5a3a }));
      lamp.position.set(0, 2.6, 0.28);
      g.add(lamp);
      d.mesh = g; d.panel = panel; d.lamp = lamp; d.group = g;
      group.add(g);
      d.panelY = 1.25;
    }
  }

  buildProps(group) {
    const barrelMat = new THREE.MeshStandardMaterial({ map: metalTexture('#5a3a24', '#24160e'), roughness: 0.8, metalness: 0.3 });
    const crateMat = new THREE.MeshStandardMaterial({ map: metalTexture('#6a5230', '#2a1e10'), roughness: 0.9 });
    const stoneMat = new THREE.MeshStandardMaterial({ map: concreteTexture('#6a6258'), color: 0x9a9084, roughness: 1 });
    const woodMat = new THREE.MeshStandardMaterial({ map: brickTexture('#5c3d26', '#42301f'), color: 0xb09a7a, roughness: 0.95 });

    for (const room of this.rooms) {
      const count = 2 + Math.floor(Math.random() * 3) + Math.floor((room.w * room.h) / 30);
      for (let i = 0; i < count; i++) {
        const p = this.randomFloorInRoom(room, 1.2);
        if (!p) continue;
        if (Math.hypot(p.x - this.exit.x, p.z - this.exit.z) < 3.5) continue;
        if (room === this.spawnRoom && Math.hypot(p.x - this.spawn.x, p.z - this.spawn.z) < 3.2) continue;
        if (!this.freeSpot(p.x, p.z, 1.0)) continue;
        const kind = Math.random();
        if (kind < 0.42) {
          const b = new THREE.Group();
          const body = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.42, 0.95, 10), barrelMat);
          body.position.y = 0.48; b.add(body);
          const ring = new THREE.Mesh(new THREE.TorusGeometry(0.4, 0.035, 4, 10), new THREE.MeshBasicMaterial({ color: 0x8a6a3a }));
          ring.rotation.x = Math.PI / 2; ring.position.y = 0.7; b.add(ring);
          b.position.set(p.x, 0, p.z);
          if (Math.random() < 0.25) b.rotation.z = 0.2;
          group.add(b);
          this.colliders.push({ kind: 'circle', x: p.x, z: p.z, r: 0.45 });
          this.occupy(p, 1.0);
        } else if (kind < 0.72) {
          const c = new THREE.Group();
          const box = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.85, 0.85), crateMat);
          box.position.y = 0.43; c.add(box);
          if (Math.random() < 0.5) {
            const box2 = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.6, 0.6), crateMat);
            box2.position.set(0.15, 1.1, -0.1); box2.rotation.y = 0.4; c.add(box2);
          }
          c.position.set(p.x, 0, p.z);
          c.rotation.y = Math.random() * 1.5;
          group.add(c);
          this.colliders.push({ kind: 'circle', x: p.x, z: p.z, r: 0.55 });
          this.occupy(p, 1.0);
        } else if (kind < 0.86) {
          const pillar = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.34, this.wallH, 8), stoneMat);
          pillar.position.set(p.x, this.wallH / 2, p.z);
          group.add(pillar);
          this.colliders.push({ kind: 'circle', x: p.x, z: p.z, r: 0.38 });
          this.occupy(p, 1.0);
        } else {
          // domestic furniture: tiny table
          const table = new THREE.Group();
          const top = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.1, 0.7), woodMat);
          top.position.y = 0.72; table.add(top);
          for (const [x, z] of [[-0.5, -0.25], [0.5, -0.25], [-0.5, 0.25], [0.5, 0.25]]) {
            const leg = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.7, 0.08), woodMat);
            leg.position.set(x, 0.36, z); table.add(leg);
          }
          table.position.set(p.x, 0, p.z);
          table.rotation.y = Math.random() * 1.5;
          group.add(table);
          this.colliders.push({ kind: 'circle', x: p.x, z: p.z, r: 0.6 });
          this.occupy(p, 1.1);
        }
      }
    }
    this.occupied = this.occupied || [];
  }

  occupy(p, min) { (this.occupied ||= []).push({ x: p.x, z: p.z, min }); }

  freeSpot(x, z, r) {
    if (!this.occupied) return true;
    return this.occupied.every((o) => Math.hypot(o.x - x, o.z - z) > Math.max(r, o.min || 1));
  }

  placeTorches() {
    const rooms = shuffle([...this.rooms]).slice(0, 7);
    const flameTex = glowTexture('#ffa842');
    for (const room of rooms) {
      const p = this.randomFloorInRoom(room, 1.1);
      if (!p) continue;
      const g = new THREE.Group();
      g.position.set(p.x, 0, p.z);
      const base = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.32, 0.7, 7), new THREE.MeshStandardMaterial({ color: 0x2a2420, roughness: 0.7, metalness: 0.4 }));
      base.position.y = 0.35; g.add(base);
      const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.2, 0.25, 8), new THREE.MeshStandardMaterial({ color: 0x4a3a28, roughness: 0.6, metalness: 0.5 }));
      bowl.position.y = 0.78; g.add(bowl);
      const flame = new THREE.Sprite(new THREE.SpriteMaterial({
        map: flameTex, color: 0xffad4a, transparent: true, opacity: 0.95,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      flame.scale.set(1.25, 1.6, 1);
      flame.position.y = 1.25;
      g.add(flame);
      const light = new THREE.PointLight(0xff9a4a, 14, 9, 2);
      light.position.set(0, 1.5, 0);
      g.add(light);
      this.group.add(g);
      this.colliders.push({ kind: 'circle', x: p.x, z: p.z, r: 0.35 });
      this.torches.push({ group: g, flame, light, baseY: 1.25, phase: Math.random() * 9 });
    }
  }

  placeItem(type, x, z, big = false) {
    const item = { type, x, z, taken: false, sprite: null, glow: null, big, bob: Math.random() * 6 };
    this.items.push(item);
    return item;
  }

  buildItems(group) {
    for (const item of this.items) {
      const tex = itemTexture(item.type);
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
        map: tex, transparent: true, depthWrite: false, color: 0xffffff,
      }));
      const s = item.big ? 1.1 : 0.72;
      sprite.scale.set(s, s, 1);
      sprite.position.set(item.x, 0.75, item.z);
      group.add(sprite);
      item.sprite = sprite;
      if (item.big || item.type === 'key') {
        const glow = new THREE.Sprite(new THREE.SpriteMaterial({
          map: glowTexture(item.type === 'key' ? '#ffcf6a' : '#8fdcff'), color: item.type === 'key' ? 0xffcf6a : 0x8fdcff,
          transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false,
        }));
        glow.scale.set(2.4, 2.4, 1);
        glow.position.set(item.x, 0.8, item.z);
        group.add(glow);
        item.glow = glow;
      }
    }
  }

  buildEnemies(group) {
    for (const e of this.enemies) {
      const tex = demonTexture(e.type, 0);
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
        map: tex, transparent: true, depthWrite: false, color: 0xffffff,
      }));
      sprite.scale.set(e.sx, e.sy, 1);
      sprite.position.set(e.x, e.y, e.z);
      group.add(sprite);
      e.sprite = sprite;
      e.walkFrame = 0;
      e.walkT = 0;
      if (e.type === 'boss') {
        const glow = new THREE.Sprite(new THREE.SpriteMaterial({
          map: glowTexture('#ff3a2a'), color: 0xff3a2a, transparent: true, opacity: 0.35,
          blending: THREE.AdditiveBlending, depthWrite: false,
        }));
        glow.scale.set(6, 6, 1); glow.position.copy(sprite.position);
        group.add(glow); e.glow = glow;
      }
    }
  }

  buildExit(group) {
    const g = new THREE.Group();
    g.position.set(this.exit.x, 0, this.exit.z);
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x3a2a1e, metalness: 0.6, roughness: 0.4, emissive: 0x1a0f08 });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(1.5, 0.16, 10, 32), frameMat);
    ring.position.y = 1.9;
    g.add(ring);
    for (const [x, z] of [[-1.3, 0.1], [1.3, 0.1]]) {
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.24, 1.1, 6), frameMat);
      leg.position.set(x, 0.55, z); g.add(leg);
    }
    const innerMat = new THREE.MeshBasicMaterial({
      color: 0x5a1a16, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false,
    });
    const inner = new THREE.Mesh(new THREE.CircleGeometry(1.36, 32), innerMat);
    inner.position.y = 1.9;
    g.add(inner);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('#ff5a3a'), color: 0xff5a3a, transparent: true, opacity: 0.4,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    glow.scale.set(5.5, 5.5, 1); glow.position.y = 1.9;
    g.add(glow);
    // floating rune particles
    const runes = [];
    for (let i = 0; i < 8; i++) {
      const r = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture('#ff6a3a'), color: 0xff6a3a, transparent: true, opacity: 0.7,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      r.scale.set(0.28, 0.28, 1);
      g.add(r); runes.push(r);
    }
    const light = new THREE.PointLight(0xff5a3a, 10, 9, 2);
    light.position.y = 1.9; g.add(light);
    group.add(g);
    this.exit.group = g; this.exit.inner = inner; this.exit.glow = glow; this.exit.runes = runes; this.exit.light = light;
  }

  buildLights(group) {
    this.ambient = new THREE.AmbientLight(0x5a4248, 0.55);
    group.add(this.ambient);
    this.hemi = new THREE.HemisphereLight(0x6a5a64, 0x1a0e10, 0.55);
    group.add(this.hemi);
    const dir = new THREE.DirectionalLight(0xffb080, 0.35);
    dir.position.set(10, 18, 6); group.add(dir);
  }

  /* ---------------- runtime queries ---------------- */
  lineOfSight(x1, z1, x2, z2) {
    const dx = x2 - x1, dz = z2 - z1;
    const dist = Math.hypot(dx, dz);
    if (dist < 0.001) return true;
    const steps = Math.ceil(dist / (this.cell * 0.35));
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      if (this.isSolidWorld(x1 + dx * t, z1 + dz * t)) return false;
    }
    return true;
  }

  rayWallDistance(ox, oz, dx, dz, maxDist) {
    // grid DDA
    const cell = this.cell;
    let gx = Math.floor(ox / cell + this.W / 2);
    let gz = Math.floor(oz / cell + this.H / 2);
    const stepX = dx > 0 ? 1 : -1;
    const stepZ = dz > 0 ? 1 : -1;
    const invDx = dx !== 0 ? 1 / Math.abs(dx) : Infinity;
    const invDz = dz !== 0 ? 1 / Math.abs(dz) : Infinity;
    const boundaryX = (gx - this.W / 2 + (dx > 0 ? 1 : 0)) * cell;
    const boundaryZ = (gz - this.H / 2 + (dz > 0 ? 1 : 0)) * cell;
    let tMaxX = dx !== 0 ? (boundaryX - ox) / dx : Infinity;
    let tMaxZ = dz !== 0 ? (boundaryZ - oz) / dz : Infinity;
    const tDeltaX = cell * invDx;
    const tDeltaZ = cell * invDz;
    let t = 0;
    for (let i = 0; i < 200; i++) {
      if (this.isSolidCell(gx, gz)) return Math.max(0, t);
      if (tMaxX < tMaxZ) { gx += stepX; t = tMaxX; tMaxX += tDeltaX; }
      else { gz += stepZ; t = tMaxZ; tMaxZ += tDeltaZ; }
      if (t > maxDist) return maxDist;
    }
    return maxDist;
  }

  updateVisuals(dt, time) {
    for (const t of this.torches) {
      const f = 0.85 + Math.sin(time * 9 + t.phase) * 0.1 + Math.sin(time * 23 + t.phase * 2) * 0.05;
      t.flame.scale.set(1.15 * f, 1.55 * f, 1);
      t.flame.position.y = t.baseY + Math.sin(time * 4 + t.phase) * 0.04;
      t.light.intensity = 12 + Math.sin(time * 11 + t.phase) * 3.5;
    }
    for (const item of this.items) {
      if (!item.sprite || item.taken) continue;
      item.sprite.position.y = 0.72 + Math.sin(time * 2.2 + item.bob) * 0.12;
      item.sprite.material.rotation = Math.sin(time * 1.1 + item.bob) * 0.06;
      if (item.glow) item.glow.position.y = item.sprite.position.y;
    }
    for (const d of this.doors) {
      if (d.progress > 0 && d.progress < 1) {
        d.progress = Math.min(1, d.progress + dt * 1.8);
        const e = 1 - Math.pow(1 - d.progress, 3);
        d.panel.position.y = 1.25 + e * 2.5;
        d.lamp.material.color.setHex(0x6aff8a);
      } else if (d.open && d.progress < 1) {
        d.progress = Math.min(1, d.progress + dt * 1.8);
        d.panel.position.y = 1.25 + (1 - Math.pow(1 - d.progress, 3)) * 2.5;
      }
    }
    // exit portal animation
    if (this.exit) {
      const unlocked = this.exit.unlocked;
      const c = unlocked ? 0x6affc0 : 0xff5a3a;
      this.exit.inner.material.color.setHex(unlocked ? 0x2affc0 : 0x5a1a16);
      this.exit.inner.material.opacity = 0.5 + Math.sin(time * 3.5) * 0.14;
      this.exit.glow.material.color.setHex(c);
      this.exit.light.color.setHex(c);
      this.exit.light.intensity = 9 + Math.sin(time * 4) * 3;
      this.exit.inner.rotation.z += dt * 0.4;
      this.exit.group.rotation.y = Math.sin(time * 0.35) * 0.05;
      this.exit.runes.forEach((r, i) => {
        const a = time * 1.4 + (i / this.exit.runes.length) * Math.PI * 2;
        r.position.set(Math.cos(a) * 1.6, 1.9 + Math.sin(time * 2 + i) * 0.7, Math.sin(a) * 0.4);
        r.material.color.setHex(c);
      });
    }
    if (this.penta) this.penta.rotation.z += dt * 0.12;
  }

  dispose() {
    if (!this.group) return;
    this.group.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of mats) {
          if (m.map && m.map !== hellWallTexture(this.config.theme)) { /* keep cached maps */ }
          m.dispose();
        }
      }
    });
    this.scene?.remove(this.group);
    this.group = null;
  }
}

import * as THREE from 'three';
import { resolveColliders } from './world.js';
import { demonTexture, glowTexture, itemTexture } from './textures.js';
import { ENEMY_STATS } from './dungeon.js';

const WEAPONS = {
  shotgun: { name: 'SHOTGUN', ammo: 'shells', pellets: 8, damage: 12, spread: 0.062, cooldown: 0.95, range: 30, kick: 1.0 },
  pistol: { name: 'PISTOL', ammo: 'bullets', pellets: 1, damage: 14, spread: 0.008, cooldown: 0.2, range: 42, kick: 0.35 },
  chaingun: { name: 'CHAINGUN', ammo: 'bullets', pellets: 1, damage: 9, spread: 0.028, cooldown: 0.085, range: 42, kick: 0.28 },
};

const tmpV = new THREE.Vector3();
const tmpV2 = new THREE.Vector3();

function raySphere(ox, oy, oz, dx, dy, dz, cx, cy, cz, r) {
  const ocx = cx - ox, ocy = cy - oy, ocz = cz - oz;
  const tca = ocx * dx + ocy * dy + ocz * dz;
  if (tca < 0) return -1;
  const d2 = ocx * ocx + ocy * ocy + ocz * ocz - tca * tca;
  const r2 = r * r;
  if (d2 > r2) return -1;
  return tca - Math.sqrt(r2 - d2);
}

export class LevelRun {
  constructor({ scene, camera, dungeon, config, audio, input, messages, onDeath, onComplete }) {
    this.scene = scene;
    this.camera = camera;
    this.dungeon = dungeon;
    this.config = config;
    this.audio = audio;
    this.input = input;
    this.messages = messages;
    this.onDeath = onDeath;
    this.onComplete = onComplete;

    this.pos = new THREE.Vector3(dungeon.spawn.x, 0, dungeon.spawn.z);
    this.vel = new THREE.Vector3();
    this.yaw = this.config.id === 'model' ? Math.PI : 0;
    this.pitch = 0;
    this.eye = 1.62;
    this.radius = 0.42;

    this.hp = 100;
    this.armor = 0;
    this.shells = 26;
    this.bullets = 120;
    this.inventory = { shotgun: true, pistol: true, chaingun: false };
    this.current = 'shotgun';
    this.keys = 0;
    this.kills = 0;
    this.totalKills = dungeon.totalEnemies;
    this.shots = 0;
    this.hits = 0;
    this.dead = false;
    this.completed = false;

    this.cooldown = 0;
    this.flash = 0;
    this.kick = 0;
    this.hitMarker = 0;
    this.damageFlash = 0;
    this.shake = 0;
    this.bob = 0;
    this.lockMsgCooldown = 0;
    this.startTime = performance.now();
    this.elapsed = 0;
    this.flowT = 0;
    this.flow = new Int16Array(dungeon.W * dungeon.H).fill(-1);
    this.flowCell = { x: -999, z: -999 };
    this.visitedT = 0;
    this.hurtSound = 0;
    this.growlT = 2;
    this.stepT = 0;
    this.lastPos = this.pos.clone();
    this.particles = [];
    this.projectiles = [];
    this.particleGeo = new THREE.BoxGeometry(0.09, 0.09, 0.09);
    this.bloodMat = new THREE.MeshBasicMaterial({ color: 0x8a1610 });
    this.goreMat = new THREE.MeshBasicMaterial({ color: 0x4a0908 });

    this.setupCamera();
    this.markVisited(true);
    this.updateFlow();
    this.input.fire = false;
  }

  setupCamera() {
    const c = this.camera;
    c.rotation.order = 'YXZ';
    c.position.set(this.pos.x, this.eye, this.pos.z);
    c.rotation.set(0, this.yaw, 0);

    this.spot = new THREE.SpotLight(0xffe3bc, 26, 25, 0.72, 0.55, 1.25);
    this.spot.position.set(0, 0.1, 0);
    this.spotTarget = new THREE.Object3D();
    this.spotTarget.position.set(0, -0.15, -3);
    c.add(this.spot); c.add(this.spotTarget);
    this.spot.target = this.spotTarget;

    this.nearLight = new THREE.PointLight(0xffcaa0, 2.2, 7, 2);
    this.nearLight.position.set(0, 0, 0.2);
    c.add(this.nearLight);

    this.scene.add(c);
    this.dungeon.updateVisuals(0, 0);

    this.audio.startAmbient('level');
  }

  /* ---------------- input ---------------- */
  applyLook(dx, dy) {
    if (this.dead || this.completed) return;
    const sens = 0.0022;
    this.yaw -= dx * sens;
    this.pitch -= dy * sens;
    this.pitch = Math.max(-1.35, Math.min(1.35, this.pitch));
  }

  onWeapon(slot) {
    const list = ['shotgun', 'pistol', 'chaingun'];
    const id = list[slot - 1];
    if (id && this.inventory[id]) {
      this.current = id;
      this.kick = 0.5;
      this.audio.reload();
      this.updateWeaponHud();
    }
  }

  onSwap() {
    const order = ['shotgun', 'pistol', 'chaingun'].filter((w) => this.inventory[w]);
    if (order.length < 2) return;
    const i = order.indexOf(this.current);
    this.current = order[(i + 1) % order.length];
    this.kick = 0.5;
    this.audio.reload();
    this.updateWeaponHud();
  }

  updateWeaponHud() {
    if (this.messages?.weapon) this.messages.weapon(this.getAmmo());
  }

  getAmmo() {
    if (this.current === 'pistol') return { label: 'BULLETS', value: '∞' };
    if (this.current === 'chaingun') return { label: 'BULLETS', value: String(this.bullets) };
    return { label: 'SHELLS', value: String(this.shells) };
  }

  get weapon() { return WEAPONS[this.current]; }

  /* ---------------- movement & collision ---------------- */
  collide(pos) {
    const d = this.dungeon;
    const cell = d.cell, r = this.radius;
    for (let iter = 0; iter < 2; iter++) {
      const cx = Math.floor(pos.x / cell + d.W / 2);
      const cz = Math.floor(pos.z / cell + d.H / 2);
      for (let z = cz - 1; z <= cz + 1; z++) {
        for (let x = cx - 1; x <= cx + 1; x++) {
          if (!d.isSolidCell(x, z)) continue;
          const minX = (x - d.W / 2) * cell, maxX = minX + cell;
          const minZ = (z - d.H / 2) * cell, maxZ = minZ + cell;
          const nx = Math.max(minX, Math.min(maxX, pos.x));
          const nz = Math.max(minZ, Math.min(maxZ, pos.z));
          let dx = pos.x - nx, dz = pos.z - nz;
          const dist = Math.hypot(dx, dz);
          if (dist < r) {
            if (dist > 0.0001) {
              const push = r - dist;
              pos.x += (dx / dist) * push;
              pos.z += (dz / dist) * push;
            } else {
              const left = Math.abs(pos.x - minX), right = Math.abs(maxX - pos.x);
              const back = Math.abs(pos.z - minZ), front = Math.abs(maxZ - pos.z);
              const m = Math.min(left, right, back, front);
              if (m === left) pos.x = minX - r;
              else if (m === right) pos.x = maxX + r;
              else if (m === back) pos.z = minZ - r;
              else pos.z = maxZ + r;
            }
          }
        }
      }
      resolveColliders(pos, r, d.colliders);
    }
    // keep inside level bounds
    const half = d.W * d.cell / 2 - r;
    pos.x = Math.max(-half, Math.min(half, pos.x));
    pos.z = Math.max(-half, Math.min(half, pos.z));
  }

  updateMovement(dt) {
    const input = this.input;
    let fwd = (input.forward || 0);
    let right = (input.right || 0);
    const len = Math.hypot(fwd, right);
    if (len > 1) { fwd /= len; right /= len; }
    const sprint = input.sprint ? 1.52 : 1;
    const speed = 4.15 * sprint;
    const sy = Math.sin(this.yaw), cy = Math.cos(this.yaw);
    const wishX = (-sy * fwd + cy * right) * speed;
    const wishZ = (-cy * fwd - sy * right) * speed;
    const accel = 1 - Math.exp(-dt * 11);
    this.vel.x += (wishX - this.vel.x) * accel;
    this.vel.z += (wishZ - this.vel.z) * accel;
    const beforeX = this.pos.x, beforeZ = this.pos.z;
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.collide(this.pos);
    // footsteps
    const moved = Math.hypot(this.pos.x - beforeX, this.pos.z - beforeZ);
    if (moved > 0.001) {
      this.stepT += moved;
      const stride = input.sprint ? 2.4 : 1.9;
      if (this.stepT > stride) {
        this.stepT = 0;
        this.audio.noise({ dur: 0.07, vol: 0.05, type: 'lowpass', freq: 320 });
      }
    }
    this.bob += moved * 2.6;
  }

  /* ---------------- pathing ---------------- */
  updateFlow() {
    const d = this.dungeon;
    const pc = d.worldToCell(this.pos.x, this.pos.z);
    this.flow.fill(-1);
    if (!d.inBounds(pc.x, pc.z)) return;
    const idx = (x, z) => z * d.W + x;
    const q = [idx(pc.x, pc.z)];
    this.flow[idx(pc.x, pc.z)] = 0;
    let head = 0;
    while (head < q.length) {
      const cur = q[head++];
      const x = cur % d.W, z = Math.floor(cur / d.W);
      const dist = this.flow[cur];
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = x + dx, nz = z + dz;
        if (!d.inBounds(nx, nz)) continue;
        if (d.isSolidCell(nx, nz)) continue;
        const ni = idx(nx, nz);
        if (this.flow[ni] !== -1) continue;
        this.flow[ni] = dist + 1;
        q.push(ni);
      }
    }
    this.flowCell = pc;
  }

  flowDir(x, z) {
    const d = this.dungeon;
    const c = d.worldToCell(x, z);
    const cur = this.flow[c.z * d.W + c.x];
    if (cur === undefined || cur < 0) return null;
    let best = cur, bx = c.x, bz = c.z;
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = c.x + dx, nz = c.z + dz;
      if (!d.inBounds(nx, nz)) continue;
      const v = this.flow[nz * d.W + nx];
      if (v >= 0 && v < best) { best = v; bx = nx; bz = nz; }
    }
    if (bx === c.x && bz === c.z) return null;
    const target = d.cellCenter(bx, bz);
    return { x: target.x, z: target.z, dist: best };
  }

  markVisited(force = false) {
    const d = this.dungeon;
    const c = d.worldToCell(this.pos.x, this.pos.z);
    for (let z = c.z - 4; z <= c.z + 4; z++) {
      for (let x = c.x - 4; x <= c.x + 4; x++) {
        if (!d.inBounds(x, z)) continue;
        if (x === c.x || z === c.z || Math.hypot(x - c.x, z - c.z) < 4.6) d.visited[z][x] = true;
      }
    }
    this.visitedT = 0;
  }

  /* ---------------- combat ---------------- */
  fire() {
    if (this.dead || this.completed) return;
    const w = this.weapon;
    if (this.cooldown > 0) return;
    if (w.ammo === 'shells' && this.shells <= 0) {
      this.cooldown = 0.35;
      this.audio.empty();
      this.messages?.message('OUT OF SHELLS — PRESS 2 FOR PISTOL', 'bad');
      return;
    }
    if (w.ammo === 'bullets' && this.current === 'chaingun' && this.bullets <= 0) {
      this.cooldown = 0.35;
      this.audio.empty();
      this.messages?.message('CHAINGUN EMPTY — PRESS 1 FOR SHOTGUN', 'bad');
      return;
    }
    this.cooldown = w.cooldown;
    this.flash = 0.075;
    this.kick = 1;
    this.shake = Math.max(this.shake, w.kick * 0.5);
    this.audio.shoot(this.current === 'pistol' ? 'pistol' : this.current === 'chaingun' ? 'chaingun' : 'shotgun');
    if (w.ammo === 'shells') this.shells -= 1;
    else if (this.current === 'chaingun') this.bullets -= 1;

    const origin = tmpV.set(this.pos.x, this.eye + this.bobOffset(), this.pos.z);
    const baseDir = tmpV2.set(
      -Math.sin(this.yaw) * Math.cos(this.pitch),
      Math.sin(this.pitch),
      -Math.cos(this.yaw) * Math.cos(this.pitch)
    );
    const d = this.dungeon;
    let anyHit = false;
    for (let p = 0; p < w.pellets; p++) {
      const sy = this.yaw + (Math.random() - 0.5) * w.spread * 2;
      const sp = this.pitch + (Math.random() - 0.5) * w.spread * 2;
      const dir = new THREE.Vector3(
        -Math.sin(sy) * Math.cos(sp),
        Math.sin(sp),
        -Math.cos(sy) * Math.cos(sp)
      );
      this.shots++;
      const wallDist = d.rayWallDistance(origin.x, origin.z, dir.x, dir.z, w.range);
      const wallPoint = origin.clone().addScaledVector(dir, wallDist);
      // vertical wall hit approximation: if ray goes above wall height or below floor
      let nearest = null, nearestT = wallDist;
      for (const e of d.enemies) {
        if (e.dead || e.deathT >= 0) continue;
        const t = raySphere(origin.x, origin.y, origin.z, dir.x, dir.y, dir.z, e.x, e.y + Math.sin(e.bob) * 0.05, e.z, e.radius * 1.05);
        if (t > 0 && t < nearestT) { nearestT = t; nearest = e; }
      }
      if (nearest) {
        const point = origin.clone().addScaledVector(dir, nearestT);
        this.damageEnemy(nearest, w.damage, point);
        anyHit = true;
      } else if (wallPoint.y < 3.2 && wallPoint.y > 0) {
        this.spawnParticles(wallPoint.x, Math.max(0.2, wallPoint.y), wallPoint.z, 2, 0x2a2018);
      }
    }
    if (anyHit) {
      this.hits++;
      this.hitMarker = 0.16;
    }
  }

  bobOffset() {
    return Math.sin(this.bob) * 0.035;
  }

  damageEnemy(e, dmg, point) {
    if (e.dead) return;
    e.hp -= dmg;
    e.hitFlash = 0.1;
    e.aggro = true;
    const pan = this.panFor(e.x, e.z);
    if (e.hp <= 0) {
      e.dead = true;
      e.deathT = 0;
      this.kills++;
      this.audio.enemyDie(pan);
      this.spawnParticles(e.x, e.y + 0.2, e.z, 10, 0x6a0d0a, 2.3);
      if (Math.random() < 0.28) this.dropItem(e.x, e.z, Math.random() < 0.55 ? 'shells' : 'health');
      else if (Math.random() < 0.04) this.dropItem(e.x, e.z, 'armor');
      if (e.glow) e.glow.visible = false;
    } else {
      this.audio.enemyHurt(pan);
      this.spawnParticles(point?.x ?? e.x, point?.y ?? e.y, point?.z ?? e.z, 5, 0x8a1610);
    }
  }

  panFor(x, z) {
    const dx = x - this.pos.x, dz = z - this.pos.z;
    const dist = Math.hypot(dx, dz) || 1;
    const rightX = Math.cos(this.yaw), rightZ = -Math.sin(this.yaw);
    return Math.max(-1, Math.min(1, (dx / dist) * rightX + (dz / dist) * rightZ)) * 0.8;
  }

  dropItem(x, z, type) {
    const d = this.dungeon;
    const item = { type, x, z, taken: false, sprite: null, glow: null, bob: Math.random() * 6, dropped: true };
    d.items.push(item);
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: itemTexture(type), transparent: true, depthWrite: false,
    }));
    sprite.scale.set(0.62, 0.62, 1);
    sprite.position.set(x, 0.6, z);
    d.group.add(sprite);
    item.sprite = sprite;
  }

  spawnParticles(x, y, z, count, color, power = 1) {
    const mat = color === 0x6a0d0a ? this.goreMat : this.bloodMat;
    for (let i = 0; i < count; i++) {
      const m = new THREE.Mesh(this.particleGeo, color === 0x2a2018 ? new THREE.MeshBasicMaterial({ color }) : mat);
      m.position.set(x, y, z);
      d3Set(m);
      this.dungeon.group.add(m);
      this.particles.push({
        mesh: m,
        vx: (Math.random() - 0.5) * 3.4 * power,
        vy: (Math.random() * 2.2 + 0.8) * power,
        vz: (Math.random() - 0.5) * 3.4 * power,
        life: 0.5 + Math.random() * 0.5,
        maxLife: 1,
      });
    }
  }

  /* ---------------- enemy AI ---------------- */
  updateEnemies(dt, time) {
    const d = this.dungeon;
    const flowStale = d.worldToCell(this.pos.x, this.pos.z);
    if (time - this.flowT > 0.32) {
      this.updateFlow();
      this.flowT = time;
    }
    const enemies = d.enemies;
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i];
      if (e.deathT >= 0) {
        e.deathT += dt;
        const t = Math.min(1, e.deathT / 0.7);
        e.sprite.scale.set(e.sx * (1 + t * 0.55), e.sy * (1 - t * 0.92), 1);
        e.sprite.material.opacity = 1 - t;
        e.sprite.position.y = e.y * (1 - t * 0.55) + 0.05;
        if (t >= 1) {
          d.group.remove(e.sprite);
          e.sprite.material.dispose();
          e.sprite = null;
          e.deathT = -2;
        }
        continue;
      }
      if (e.dead) continue;
      e.cool -= dt;
      e.growlT -= dt;
      e.bob += dt * (e.state === 'idle' ? 1.2 : 6);
      if (e.hitFlash > 0) {
        e.hitFlash -= dt;
        e.sprite.material.color.setHex(e.hitFlash > 0 ? 0xffe0d0 : 0xffffff);
      }
      const dx = this.pos.x - e.x, dz = this.pos.z - e.z;
      const dist = Math.hypot(dx, dz);
      const los = dist < 24 && d.lineOfSight(e.x, e.z, this.pos.x, this.pos.z);
      if (!e.aggro && ((los && dist < 19) || dist < 4.5)) {
        e.aggro = true;
        e.state = 'hunt';
        this.audio.growl(this.panFor(e.x, e.z));
      }
      if (!e.aggro) {
        // idle sway
        e.sprite.position.y = e.y + Math.sin(e.bob) * 0.035;
        if (e.glow) e.glow.position.copy(e.sprite.position);
        continue;
      }
      if (e.growlT <= 0 && dist < 16) {
        e.growlT = 3 + Math.random() * 5;
        this.audio.growl(this.panFor(e.x, e.z));
      }

      // attacking
      const canSee = los;
      if (e.ranged && canSee && dist < e.range && e.cool <= 0) {
        e.cool = e.cooldown * (0.85 + Math.random() * 0.35);
        this.enemyShoot(e, dist);
      } else if (e.melee && dist < e.range + 0.4 && e.cool <= 0) {
        e.cool = e.cooldown;
        e.lunge = 0.22;
        this.hurtPlayer(e.dmg, e.type);
        this.audio.growl(this.panFor(e.x, e.z));
      }

      // movement
      let tx = null, tz = null;
      if (canSee && dist < 10) {
        tx = this.pos.x; tz = this.pos.z;
      } else {
        const f = this.flowDir(e.x, e.z);
        if (f) { tx = f.x; tz = f.z; }
      }
      if (tx !== null) {
        const mdx = tx - e.x, mdz = tz - e.z;
        const md = Math.hypot(mdx, mdz);
        if (md > 0.08) {
          let speed = e.speed;
          if (e.state === 'idle') e.state = 'hunt';
          e.state = 'hunt';
          // keep slight distance for ranged enemies
          const stop = e.melee ? 1.0 : (e.type === 'boss' ? 4.5 : 3.2);
          if (dist > stop) {
            let vx = (mdx / md) * speed, vz = (mdz / md) * speed;
            // separation
            for (const o of enemies) {
              if (o === e || o.dead || o.deathT >= 0) continue;
              const sx = e.x - o.x, sz = e.z - o.z;
              const sd = Math.hypot(sx, sz);
              if (sd < 1.0 && sd > 0.001) {
                vx += (sx / sd) * 1.6;
                vz += (sz / sd) * 1.6;
              }
            }
            e.x += vx * dt; e.z += vz * dt;
          }
        }
      }
      // lunge recovery
      if (e.lunge > 0) e.lunge = Math.max(0, e.lunge - dt);

      // collide with walls + props
      const ep = { x: e.x, z: e.z };
      this.collideEnemy(ep, e.radius * 0.55);
      e.x = ep.x; e.z = ep.z;

      // keep out of player
      const pdx = e.x - this.pos.x, pdz = e.z - this.pos.z;
      const pd = Math.hypot(pdx, pdz);
      const minD = 0.55 + e.radius * 0.35;
      if (pd < minD && pd > 0.001) {
        e.x = this.pos.x + (pdx / pd) * minD;
        e.z = this.pos.z + (pdz / pd) * minD;
      }

      // animation
      const moving = md > 0.1;
      e.walkT += dt;
      const frame = moving ? Math.floor(e.walkT * 5) % 2 : 0;
      if (frame !== e.walkFrame || e.state === 'idle') {
        e.walkFrame = frame;
        const tex = demonTexture(e.type, frame);
        if (e.sprite.material.map !== tex) {
          e.sprite.material.map = tex;
          e.sprite.material.needsUpdate = true;
        }
      }
      const bobY = Math.sin(e.bob) * (moving ? 0.09 : 0.035);
      e.sprite.position.set(e.x, e.y + bobY + (e.lunge > 0 ? 0.12 : 0), e.z);
      e.sprite.material.rotation = moving ? Math.sin(e.bob) * 0.03 : 0;
      if (e.glow) e.glow.position.set(e.x, e.y + bobY, e.z);
    }
  }

  collideEnemy(pos, r) {
    const d = this.dungeon;
    const cell = d.cell;
    const cx = Math.floor(pos.x / cell + d.W / 2);
    const cz = Math.floor(pos.z / cell + d.H / 2);
    for (let z = cz - 1; z <= cz + 1; z++) {
      for (let x = cx - 1; x <= cx + 1; x++) {
        if (!d.isSolidCell(x, z)) continue;
        const minX = (x - d.W / 2) * cell, maxX = minX + cell;
        const minZ = (z - d.H / 2) * cell, maxZ = minZ + cell;
        const nx = Math.max(minX, Math.min(maxX, pos.x));
        const nz = Math.max(minZ, Math.min(maxZ, pos.z));
        const ddx = pos.x - nx, ddz = pos.z - nz;
        const dist = Math.hypot(ddx, ddz);
        if (dist < r && dist > 0.0001) {
          const push = r - dist;
          pos.x += (ddx / dist) * push;
          pos.z += (ddz / dist) * push;
        }
      }
    }
    resolveColliders({ get x() { return pos.x; }, set x(v) { pos.x = v; }, get z() { return pos.z; }, set z(v) { pos.z = v; } }, r, d.colliders);
  }

  enemyShoot(e, dist) {
    const sx = e.x, sz = e.z;
    const tx = this.pos.x, tz = this.pos.z;
    const baseA = Math.atan2(tx - sx, tz - sz);
    const count = e.type === 'boss' ? 3 : 1;
    for (let i = 0; i < count; i++) {
      const a = baseA + (i - (count - 1) / 2) * 0.13 + (Math.random() - 0.5) * 0.05;
      const speed = e.type === 'boss' ? 8.5 : 7.2;
      const mesh = new THREE.Mesh(new THREE.SphereGeometry(e.type === 'boss' ? 0.3 : 0.2, 8, 6), new THREE.MeshBasicMaterial({ color: e.type === 'boss' ? 0xff3a20 : 0xff8a3a }));
      mesh.position.set(sx, e.y + 0.1, sz);
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture('#ff7a3a'), color: 0xff7a3a, transparent: true, opacity: 0.85,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      glow.scale.set(0.9, 0.9, 1); mesh.add(glow);
      this.dungeon.group.add(mesh);
      this.projectiles.push({
        mesh, x: sx, z: sz, y: e.y + 0.1,
        vx: Math.sin(a) * speed, vz: Math.cos(a) * speed,
        life: 4, dmg: e.dmg, radius: 0.2,
      });
    }
    this.audio.tone({ freq: 300, freq2: 90, type: 'sawtooth', dur: 0.22, vol: 0.09, pan: this.panFor(e.x, e.z) });
  }

  updateProjectiles(dt) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      p.x += p.vx * dt; p.z += p.vz * dt;
      p.mesh.position.set(p.x, p.y, p.z);
      p.mesh.rotation.x += dt * 7;
      let remove = false;
      if (p.life <= 0) remove = true;
      if (this.dungeon.isSolidWorld(p.x, p.z)) {
        remove = true;
        this.spawnParticles(p.x, p.y, p.z, 5, 0x2a2018, 0.8);
      }
      const ddx = p.x - this.pos.x, ddz = p.z - this.pos.z;
      if (Math.hypot(ddx, ddz) < 0.62) {
        remove = true;
        this.hurtPlayer(p.dmg, 'fireball');
        this.spawnParticles(p.x, p.y, p.z, 6, 0x8a1610, 0.8);
      }
      if (remove) {
        this.dungeon.group.remove(p.mesh);
        p.mesh.geometry.dispose(); p.mesh.material.dispose();
        this.projectiles.splice(i, 1);
      }
    }
  }

  hurtPlayer(amount, source) {
    if (this.dead || this.completed) return;
    let dmg = amount;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.6);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    this.hp -= dmg;
    this.damageFlash = Math.min(1, this.damageFlash + 0.55);
    this.shake = Math.max(this.shake, 0.75);
    if (this.hurtSound <= 0) {
      this.audio.playerHurt();
      this.hurtSound = 0.22;
    }
    if (this.hp <= 0) {
      this.hp = 0;
      this.dead = true;
      this.audio.stopAmbient();
      this.audio.death();
      this.onDeath?.({ kills: this.kills, keys: this.keys });
    }
  }

  /* ---------------- items & doors ---------------- */
  updateItems(time) {
    const d = this.dungeon;
    for (const item of d.items) {
      if (item.taken) continue;
      const dx = item.x - this.pos.x, dz = item.z - this.pos.z;
      if (Math.hypot(dx, dz) < 1.15) {
        this.pickup(item);
        continue;
      }
      if (item.sprite) {
        item.sprite.position.y = 0.72 + Math.sin(time * 2.2 + item.bob) * 0.12;
        if (item.glow) item.glow.position.y = item.sprite.position.y;
      }
    }
  }

  pickup(item) {
    const d = this.dungeon;
    item.taken = true;
    if (item.sprite) { d.group.remove(item.sprite); item.sprite.material.dispose(); item.sprite = null; }
    if (item.glow) { d.group.remove(item.glow); item.glow.material.dispose(); item.glow = null; }
    if (item.type === 'key') {
      this.keys = 1;
      d.exit.unlocked = true;
      this.audio.key();
      this.messages?.message('SIGIL KEY ACQUIRED — THE PORTAL IS OPEN', 'good');
    } else if (item.type === 'health') {
      const before = this.hp;
      this.hp = Math.min(100, this.hp + 25);
      this.audio.pickup();
      this.messages?.message(`+${Math.round(this.hp - before)} HEALTH`);
    } else if (item.type === 'armor') {
      const before = this.armor;
      this.armor = Math.min(100, this.armor + 30);
      this.audio.pickup();
      this.messages?.message(`+${Math.round(this.armor - before)} ARMOR`);
    } else if (item.type === 'shells') {
      this.shells += 8;
      this.audio.pickup();
      this.messages?.message('+8 SHELLS');
    } else if (item.type === 'chaingun') {
      this.inventory.chaingun = true;
      this.bullets += 120;
      this.current = 'chaingun';
      this.audio.pickup();
      this.messages?.message('CHAINGUN ACQUIRED — HOLD FIRE', 'good');
      this.updateWeaponHud();
    }
  }

  updateDoors(dt) {
    const d = this.dungeon;
    for (const door of d.doors) {
      if (door.open) continue;
      const p = d.cellCenter(door.cx, door.cz);
      let near = Math.hypot(p.x - this.pos.x, p.z - this.pos.z) < 3.4;
      if (!near) {
        for (const e of d.enemies) {
          if (e.dead || e.deathT >= 0) continue;
          if (Math.hypot(p.x - e.x, p.z - e.z) < 2.0) { near = true; break; }
        }
      }
      if (near) {
        door.open = true;
        door.progress = 0.001;
        this.audio.door();
      }
    }
  }

  /* ---------------- frame ---------------- */
  update(dt, time) {
    if (this.dead || this.completed) {
      this.updateParticles(dt);
      this.updateCamera(dt, time);
      return;
    }
    this.elapsed = (performance.now() - this.startTime) / 1000;
    this.cooldown = Math.max(0, this.cooldown - dt);
    this.flash = Math.max(0, this.flash - dt);
    this.kick = Math.max(0, this.kick - dt * 6);
    this.hitMarker = Math.max(0, this.hitMarker - dt);
    this.damageFlash = Math.max(0, this.damageFlash - dt * 2.3);
    this.shake = Math.max(0, this.shake - dt * 2.2);
    this.hurtSound = Math.max(0, this.hurtSound - dt);
    this.lockMsgCooldown = Math.max(0, this.lockMsgCooldown - dt);

    const input = this.input;
    this.updateMovement(dt);
    if (input.fire) this.fire();

    this.updateEnemies(dt, time);
    this.updateProjectiles(dt);
    this.updateItems(time);
    this.updateDoors(dt);
    this.updateParticles(dt);
    this.dungeon.updateVisuals(dt, time);

    this.visitedT += dt;
    if (this.visitedT > 0.2) this.markVisited();

    // portal
    const ex = this.dungeon.exit;
    const dd = Math.hypot(this.pos.x - ex.x, this.pos.z - ex.z);
    if (dd < 1.65) {
      if (!ex.unlocked) {
        if (this.lockMsgCooldown <= 0) {
          this.lockMsgCooldown = 2.8;
          this.audio.locked();
          this.messages?.message('SEALED. THE SIGIL KEY IS STILL HIDDEN IN THIS HOUSE.', 'bad');
        }
      } else if (!this.completed) {
        this.completed = true;
        this.audio.portal();
        this.audio.stopAmbient();
        setTimeout(() => this.audio.clear(), 250);
        this.onComplete?.({
          kills: this.kills, total: this.totalKills,
          accuracy: this.shots ? Math.round((this.hits / this.shots) * 100) : 0,
          time: this.elapsed, keys: this.keys,
        });
      }
    }

    this.updateCamera(dt, time);
  }

  updateCamera(dt, time) {
    const c = this.camera;
    const bobY = Math.sin(this.bob) * 0.028;
    const shakeX = (Math.random() - 0.5) * this.shake * 0.09;
    const shakeY = (Math.random() - 0.5) * this.shake * 0.09;
    c.position.set(this.pos.x + shakeX, this.eye + bobY + shakeY, this.pos.z);
    const kickPitch = this.kick * 0.035;
    c.rotation.set(this.pitch + kickPitch, this.yaw, Math.sin(time * 37) * this.shake * 0.012);
    // muzzle light
    if (this.spot) {
      this.spot.intensity = 25 + this.flash * 500;
      this.spot.color.setHex(this.flash > 0 ? 0xfff0d0 : 0xffe3bc);
    }
  }

  updateParticles(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      p.vy -= 9.5 * dt;
      p.mesh.position.x += p.vx * dt;
      p.mesh.position.y += p.vy * dt;
      p.mesh.position.z += p.vz * dt;
      if (p.mesh.position.y < 0.03) { p.mesh.position.y = 0.03; p.vy *= -0.25; p.vx *= 0.6; p.vz *= 0.6; }
      p.mesh.rotation.x += dt * 8; p.mesh.rotation.y += dt * 6;
      if (p.life <= 0) {
        this.dungeon.group.remove(p.mesh);
        this.particles.splice(i, 1);
      }
    }
  }

  getObjective() {
    if (this.keys) return { line: 'Reach the exit portal', sub: 'THE SIGIL IS YOURS — STEP INTO THE LIGHT' };
    return { line: 'Find the sigil key', sub: 'FIND THE KEY, THEN REACH THE PORTAL' };
  }

  dispose() {
    this.audio.stopAmbient();
    this.camera.remove(this.spot, this.spotTarget, this.nearLight);
    this.scene.remove(this.camera);
    for (const p of this.projectiles) {
      this.dungeon.group?.remove(p.mesh);
      p.mesh.geometry.dispose(); p.mesh.material.dispose();
    }
    for (const p of this.particles) this.dungeon.group?.remove(p.mesh);
    this.projectiles = []; this.particles = [];
    this.dungeon.dispose();
  }
}

