    ui.prompt.classList.add('hidden');
    ui.touchEnter.classList.add('hidden');
  }
  ui.fire.style.display = mode === 'level' ? '' : 'none';
  ui.swap.style.display = mode === 'level' ? '' : 'none';
  ui.mapBtn.style.display = mode === 'neighborhood' ? '' : 'none';
