import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const out = process.argv[2] || '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => { errors.push('PAGEERROR ' + e.message); console.log('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push('CONSOLE ' + m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1800);
await page.screenshot({ path: `${out}/01-title.png` });
await page.click('#start-btn');
await page.waitForTimeout(1500);
await page.screenshot({ path: `${out}/02-neighborhood.png` });
// jump to house
await page.evaluate(() => window.__pines.enterHouse('split'));
await page.waitForTimeout(1200);
await page.screenshot({ path: `${out}/03-intro.png` });
await page.click('#intro-btn');
await page.waitForTimeout(2200);
await page.screenshot({ path: `${out}/04-level.png` });
console.log('STATE', await page.evaluate(() => window.__pines.state));
console.log('LEVEL', await page.evaluate(() => {
  const l = window.__pines.level;
  if (!l) return null;
  return { hp: l.hp, enemies: l.totalEnemies, pos: [l.pos.x, l.pos.z], keys: l.keys, room: l.dungeon.rooms.length, doors: l.dungeon.doors.length, items: l.dungeon.items.length };
}));
// look around / move
await page.mouse.move(720, 450);
await page.mouse.down();
await page.waitForTimeout(120);
await page.mouse.up();
await page.keyboard.down('w');
await page.waitForTimeout(700);
await page.keyboard.up('w');
await page.screenshot({ path: `${out}/05-moved.png` });
// fire once
await page.mouse.down();
await page.waitForTimeout(110);
await page.mouse.up();
await page.waitForTimeout(120);
await page.screenshot({ path: `${out}/06-fired.png` });
console.log('LEVEL2', await page.evaluate(() => {
  const l = window.__pines.level;
  return l ? { hp: l.hp, shells: l.shells, shots: l.shots, pos: [l.pos.x, l.pos.z], kills: l.kills } : null;
}));
console.log('ERRORS', errors.length);
await browser.close();

