await page.mouse.move(720, 450);
await page.mouse.move(820, 450);
await page.waitForTimeout(200);
const afterTurn = await page.evaluate(() => ({ yaw: window.__pines.level.yaw }));
// move forward
await page.keyboard.down('w');
await page.waitForTimeout(900);
await page.keyboard.up('w');
const afterMove = await page.evaluate(() => ({ pos: [window.__pines.level.pos.x, window.__pines.level.pos.z] }));
await page.screenshot({ path: `${out}/05-moved.png` });
// fire
await page.mouse.down();
await page.waitForTimeout(80);
await page.mouse.up();
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/06-fired.png` });
console.log('TURN', before.yaw, '->', afterTurn.yaw, 'MOVE', before.pos, '->', afterMove.pos);
