  if (!await waitState('results')) {
    console.log('EXIT FAIL', id, await page.evaluate(() => ({state:window.__pines.state, keys:window.__pines.level?.keys, pos:[+window.__pines.level.pos.x.toFixed(1),+window.__pines.level.pos.z.toFixed(1)], exit:[+window.__pines.level.dungeon.exit.x.toFixed(1),+window.__pines.level.dungeon.exit.z.toFixed(1)], completed:window.__pines.level.completed})));
