  .title-meta { display: none; }
  .map-body { grid-template-columns: 1fr; gap: 14px; }
  .map-canvas-wrap { width: min(230px, 62vw); margin: 0 auto; }
  .map-list { max-height: none; overflow: visible; gap: 5px; }
  .map-item { padding: 7px 9px; gap: 9px; }
  .map-item .mi-icon { width: 22px; height: 22px; font-size: 10px; }
  .map-item .mi-name { font-size: 9px; }
  .map-item .mi-sub { font-size: 7px; }
  .map-item .mi-status { font-size: 7px; }
  .map-card { padding: 16px 15px; width: 100%; }
  .map-head { margin-bottom: 12px; }
  .map-head h2 { font-size: 22px; }
  .map-foot { margin-top: 10px; padding-top: 9px; font-size: 7px; }
  .menu-card, .result-card, .death-card, .ending-card, .intro-card { padding: 26px 20px 22px; }
  .intro-card h2, .result-card h2 { font-size: 30px; }
  .map-hint span { display: none; }
  .title-screen { justify-content: center; padding-bottom: calc(20px + var(--safe-bottom)); }
  .blurb { font-size: 10px; }
  #start-btn { margin-top: 20px; }
  .title-foot .build { display: none; }
}

/* keep level touch buttons above the Doom HUD */
@media (max-width: 820px) {
  #hud-level:not(.hidden) ~ #touch .touch-right { bottom: calc(84px + var(--safe-bottom)); }
  .tbtn.swap, .tbtn.map { order: 1; }
  .tbtn.use { order: 2; }
  .tbtn.fire { order: 3; }
}

