input.content:
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const out = '/tmp/opencode/mobile'; mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, args: [...config.browser.launchOptions.args, '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding'], timeout: 30000 });
const context = await browser.newContext({
  viewport: { width: 390, height: 844 },
  screen: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
  userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1',
});
const page = await context.newPage();
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.stack); });
page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('favicon')) { errors.push(m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(1200);
console.log('TOUCH?', await page.evaluate(() => ({ coarse: matchMedia('(pointer: coarse)').matches, ontouch: 'ontouchstart' in window, w: innerWidth, h: innerHeight })));
await page.screenshot({ path: `${out}/01-title.png` });

await page.tap('#start-btn');
await page.waitForTimeout(1400);
await page.evaluate(() => { const G=window.__pines._G; G.dialogue.open=false; document.getElementById('dialogue').classList.add('hidden'); });
await page.waitForTimeout(700);
await page.screenshot({ path: `${out}/02-neighborhood.png` });
console.log('NEIGHBORHOOD OVERLAP', await page.evaluate(() => {
  const a=document.querySelector('.nh-panel').getBoundingClientRect();
  const b=document.querySelector('.compass').getBoundingClientRect();
  const overlap = !(a.right < b.left || b.right < a.left || a.bottom < b.top || b.bottom < a.top);
  return { panel:[a.left,a.top,a.right,a.bottom].map(Math.round), compass:[b.left,b.top,b.right,b.bottom].map(Math.round), overlap };
}));

// map via touch button
await page.tap('#btn-map');
await page.waitForTimeout(700);
await page.screenshot({ path: `${out}/03-map.png` });
console.log('MAP', await page.evaluate(() => {
  const c=document.querySelector('.map-card').getBoundingClientRect();
  const f=document.querySelector('.map-foot').getBoundingClientRect();
  const l=document.querySelector('.map-list').getBoundingClientRect();
  return { card:[c.top,c.bottom,c.height].map(Math.round), foot:[f.top,f.bottom].map(Math.round), list:[l.top,l.bottom].map(Math.round), inner:[innerWidth,innerHeight], listOverflow:getComputedStyle(document.querySelector('.map-list')).overflowY };
}));
await page.tap('#map-close');
await page.waitForTimeout(500);

// touch joystick
async function touchDrag(x1,y1,x2,y2,steps=12,hold=60) {
  const cdp = await context.newCDPSession(page);
  await cdp.send('Input.dispatchTouchEvent', { type:'touchStart', touchPoints:[{x:x1,y:y1,id:1}] });
  for (let i=1;i<=steps;i++) {
    await cdp.send('Input.dispatchTouchEvent', { type:'touchMove', touchPoints:[{x:x1+(x2-x1)*i/steps,y:y1+(y2-y1)*i/steps,id:1}] });
    await page.waitForTimeout(hold);
  }
  await cdp.send('Input.dispatchTouchEvent', { type:'touchEnd', touchPoints:[] });
  await cdp.detach();
}
const before = await page.evaluate(() => ({x:window.__pines.player.pos.x,z:window.__pines.player.pos.z}));
await touchDrag(100, 620, 100, 540, 14, 70);
const after = await page.evaluate(() => ({x:window.__pines.player.pos.x,z:window.__pines.player.pos.z}));
console.log('STICK MOVE', before, '->', after, 'delta', Math.hypot(after.x-before.x, after.z-before.z).toFixed(2));

// walk up to a door and use the touch ENTER button
await page.evaluate(() => {
  const h = window.__pines.houses[0];
  const e = h.entrance;
  window.__pines.player.pos.set(e.x, 0, e.z + 1.4);
  window.__pines.player.angle = Math.PI;
  window.__pines._G.camYaw = 0;
});
await page.waitForTimeout(1200);
console.log('TOUCH ENTER', await page.evaluate(() => ({ hidden: document.getElementById('touch-enter').classList.contains('hidden'), prompt: document.getElementById('prompt-text').textContent, state: window.__pines.state })));
await page.screenshot({ path: `${out}/04-door-prompt.png` });
await page.tap('#touch-enter');
await page.waitForTimeout(900);
console.log('INTRO', await page.evaluate(() => ({ state: window.__pines.state, hidden: document.getElementById('level-intro').classList.contains('hidden') })));
await page.screenshot({ path: `${out}/05-level-intro.png` });
await page.tap('#intro-btn');
await page.waitForTimeout(2600);
console.log('LEVEL', await page.evaluate(() => ({ state: window.__pines.state, hasLevel: !!window.__pines.level })));
await page.screenshot({ path: `${out}/06-level.png` });
console.log('LEVEL HUD', await page.evaluate(() => {
  const sel = { touch:'#touch', fire:'#btn-fire', use:'#btn-use', swap:'#btn-swap', hud:'.doom-hud', weapon:'.weapon-strip', obj:'.obj-panel', minimap:'.minimap-wrap', pause:'#pause-btn' };
  const r = {};
  for (const [k,id] of Object.entries(sel)) { const el=document.querySelector(id); const b=el.getBoundingClientRect(); const s=getComputedStyle(el); r[k]={x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height),display:s.display,hidden:el.classList.contains('hidden')}; }
  return r;
}));

// fire via touch
const ammoBefore = await page.evaluate(() => window.__pines.level.getAmmo().value);
await page.tap('#btn-fire');
await page.waitForTimeout(900);
const ammoAfter = await page.evaluate(() => window.__pines.level.getAmmo().value);
console.log('FIRE', ammoBefore, '->', ammoAfter, 'shots', await page.evaluate(() => window.__pines.level.shots));

// swap weapon
await page.tap('#btn-swap');
await page.waitForTimeout(500);
console.log('SWAP', await page.evaluate(() => window.__pines.level.weapon.name));

// look drag on right side
const yawBefore = await page.evaluate(() => window.__pines.level.yaw);
await touchDrag(300, 500, 340, 500, 8, 40);
const yawAfter = await page.evaluate(() => window.__pines.level.yaw);
console.log('LOOK', yawBefore?.toFixed?.(2), '->', yawAfter?.toFixed?.(2));

// death + retry
await page.evaluate(() => window.__pines.level.hurtPlayer(999));
await page.waitForTimeout(1200);
console.log('DEATH', await page.evaluate(() => ({ state: window.__pines.state, hidden: document.getElementById('death').classList.contains('hidden') })));
await page.screenshot({ path: `${out}/07-death.png` });
await page.tap('#retry-btn');
await page.waitForTimeout(2200);
console.log('RETRY', await page.evaluate(() => ({ state: window.__pines.state, hasLevel: !!window.__pines.level, introHidden:document.getElementById('level-intro').classList.contains('hidden'), health:window.__pines.level?.health })));
await page.screenshot({ path: `${out}/08-retry.png` });

// die again and flee
await page.evaluate(() => window.__pines.enterHouse('bunker'));
await page.waitForTimeout(2000);
await page.evaluate(() => window.__pines.level.hurtPlayer(999));
await page.waitForTimeout(1000);
await page.tap('#death-flee-btn');
await page.waitForTimeout(1800);
console.log('FLEE', await page.evaluate(() => ({ state: window.__pines.state, touchHidden:document.getElementById('touch').classList.contains('hidden'), player:[+window.__pines.player.pos.x.toFixed(1),+window.__pines.player.pos.z.toFixed(1)] })));
await page.screenshot({ path: `${out}/09-flee.png` });

// results flow via direct complete
await page.evaluate(() => window.__pines.enterHouse('split'));
await page.waitForTimeout(1800);
await page.evaluate(() => { const l=window.__pines.level; const k=l.dungeon.items.find(i=>i.type==='key'); l.pos.set(k.x,0,k.z); });
await page.waitForTimeout(1000);
await page.evaluate(() => { const l=window.__pines.level; l.pos.set(l.dungeon.exit.x,0,l.dungeon.exit.z); });
await page.waitForFunction(() => window.__pines.state === 'results', null, { timeout: 9000, polling: 150 }).catch(()=>{});
console.log('RESULTS', await page.evaluate(() => ({ state: window.__pines.state, hidden: document.getElementById('results').classList.contains('hidden') })));
await page.screenshot({ path: `${out}/10-results.png` });

console.log('ERRORS', errors.length, errors);
await browser.close();

