await page.screenshot({ path: `${out}/intro-raw.png` });
await page.evaluate(() => { document.getElementById('level-intro').style.visibility = ''; document.getElementById('level-intro').classList.add('hidden'); window.__pines._G.state='neighborhood'; });
await browser.close();

