});
await page.waitForTimeout(1000);
console.log('NEAR', await page.evaluate(() => ({ near: window.__pines._G.near?.type, enter: document.getElementById('touch-enter').textContent, hidden: document.getElementById('touch-enter').classList.contains('hidden') })));
await page.screenshot({ path: `${out}/03-door.png` });
await page.tap('#touch-enter');
await page.waitForTimeout(900);
console.log('INTRO', await page.evaluate(() => {
  const b=document.querySelector('.intro-card').getBoundingClientRect();
  return { state: window.__pines.state, card:[b.top,b.bottom,b.height].map(Math.round), vh:innerHeight, overflow:b.top<0||b.bottom>innerHeight };
}));
await page.screenshot({ path: `${out}/04-intro.png` });
await page.tap('#intro-btn');
await page.waitForTimeout(2400);
console.log('LVL', await page.evaluate(() => {
  const box = (s)=>{const b=document.querySelector(s).getBoundingClientRect(); return [b.left,b.top,b.right,b.bottom].map(Math.round)};
  return { obj:box('.obj-panel'), mini:box('.minimap-wrap'), pause:box('#pause-btn'), fire:box('#btn-fire'), use:box('#btn-use'), swap:box('#btn-swap'), hud:box('.doom-hud'), weapon:box('.weapon-strip') };
}));
await page.screenshot({ path: `${out}/05-level.png` });
await page.tap('#pause-btn');
await page.waitForTimeout(700);
await page.screenshot({ path: `${out}/06-pause.png` });
console.log('PAUSE', await page.evaluate(() => window.__pines.state));
console.log('ERRORS', errors);
await browser.close();

