import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${runtime}/display`, 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, args: [...config.browser.launchOptions.args, '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors=[]; page.on('pageerror', e=>{errors.push(e.message); console.log('PAGEERROR', e.message)});
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(900);
await page.click('#start-btn');
await page.waitForTimeout(2200);
for (let i=0;i<4;i++){ const open=await page.evaluate(()=>window.__pines._G.dialogue.open); if(!open) break; await page.click('#dialogue'); await page.waitForTimeout(300); }
await page.waitForTimeout(500);
async function enter(id){
  const t=Date.now();
  await page.evaluate((id)=>window.__pines.enterHouse(id), id);
  for (let i=0;i<40;i++){
    const s=await page.evaluate(()=>({state:window.__pines.state, tr:window.__pines._G.transition, intro:document.getElementById('level-intro').classList.contains('hidden'), has:!!window.__pines.level}));
    if (s.state==='level' && !s.tr && s.has) { console.log(id,'entered in',Date.now()-t,'ms',s); return true; }
    await page.waitForTimeout(250);
  }
  console.log(id,'ENTER TIMEOUT',await page.evaluate(()=>({state:window.__pines.state,tr:window.__pines._G.transition,introHidden:document.getElementById('level-intro').classList.contains('hidden'),has:!!window.__pines.level,btn:document.getElementById('intro-btn').textContent})));
  return false;
}
async function finish(id){
  await page.evaluate(()=>{ const l=window.__pines.level,k=l.dungeon.items.find(i=>i.type==='key'); l.pos.set(k.x,0,k.z); });
  await page.waitForTimeout(900);
  await page.evaluate(()=>{ const l=window.__pines.level; l.pos.set(l.dungeon.exit.x,0,l.dungeon.exit.z); });
  for (let i=0;i<40;i++){ const s=await page.evaluate(()=>window.__pines.state); if(s==='results'){break;} await page.waitForTimeout(250); }
  console.log(id,'RESULTS', await page.evaluate(()=>window.__pines.state));
  await page.click('#results-btn');
  for (let i=0;i<50;i++){ const s=await page.evaluate(()=>({state:window.__pines.state,tr:window.__pines._G.transition})); if(s.state==='neighborhood'&&!s.tr){ console.log(id,'BACK',s); return; } await page.waitForTimeout(250); }
  console.log(id,'BACK TIMEOUT',await page.evaluate(()=>({state:window.__pines.state,tr:window.__pines._G.transition})));
}
for (const id of ['split','bunker','carnage','concept']) {
  if (!await enter(id)) break;
  await finish(id);
}
console.log('CLEARED', await page.evaluate(()=>window.__pines.save.cleared));
console.log('ERRORS',errors);
await browser.close();

